    if pred_tensor.dim() not in [2, 3, 4]:
        return (False, f"Expected 2D, 3D, or 4D tensor, got {pred_tensor.dim()}D with shape {pred_tensor.shape}")

    # Find the mel_bins dimension (should be 224)
    # Check all dimensions to find where 224 appears
    shape = pred_tensor.shape
    mel_dim_value = None
    mel_dim_idx = None

    # For different tensor layouts, determine mel_bins dimension
    if pred_tensor.dim() == 2:
        # (mel_bins, time_frames) - dim 0 should be 224
        mel_dim_value = shape[0]
        mel_dim_idx = 0
    elif pred_tensor.dim() == 3:
        # (segments, mel_bins, time_frames) - dim 1 should be 224
        mel_dim_value = shape[1]
        mel_dim_idx = 1
    elif pred_tensor.dim() == 4:
        # Could be (segments, channels, mel_bins, time_frames) - dim 2 should be 224
        # Or other layouts - check all dims for 224
        if shape[2] == 224:
            mel_dim_value = shape[2]
            mel_dim_idx = 2
        elif shape[1] == 224:
            mel_dim_value = shape[1]
            mel_dim_idx = 1
        elif shape[3] == 224:
            mel_dim_value = shape[3]
            mel_dim_idx = 3
        else:
            # Try to find 224 anywhere
            for i, s in enumerate(shape):
                if s == 224:
                    mel_dim_value = s
                    mel_dim_idx = i
                    break

    if mel_dim_value != 224:
        # Check if 224 appears anywhere in the shape
        if 224 not in shape:
            return (False, f"Expected 224 mel bins somewhere in tensor shape, got shape {list(shape)}")
        else:
            # 224 is present but not where expected
            mel_dim_value = 224

    # For segmented tensors, verify segment count >= 1
    if pred_tensor.dim() >= 3:
        num_segments = shape[0]
        if num_segments < 1:
            return (False, f"Expected at least 1 segment, got {num_segments}")

    # Check for NaN or Inf values
    if torch.isnan(pred_tensor).any():
        return (False, "Predicted tensor contains NaN values")
    if torch.isinf(pred_tensor).any():
        return (False, "Predicted tensor contains Inf values")

    # Step 3: Validate numerical properties (normalization check)
    pred_std = pred_tensor.std().item()
    pred_mean = pred_tensor.mean().item()
    pred_all_zero = (pred_tensor == 0).all().item()

    if not pred_all_zero:
        if pred_std < 0.01:
            return (False, f"Tensor std too low ({pred_std:.4f}), normalization may not have been applied")

    # Check that normalization was applied - values should be in reasonable range
    abs_max = pred_tensor.abs().max().item()
