import os
import pandas as pd
import numpy as np
from PIL import Image
from collections import defaultdict


def compute_fifo_holding_days():
    """Recompute FIFO holding days from the source dataset as ground truth."""
    trade_log_path = "benchmark/datasets/LLM-Trading-Lab/Experiments/chatgpt_micro-cap/csv_files/Trade Log.csv"
    trades_df = pd.read_csv(trade_log_path, parse_dates=["Date"])
    trades_df = trades_df.sort_values("Date")

    holding_days = []
    for ticker, tdf in trades_df.groupby("Ticker"):
        buy_queue = []
        for _, row in tdf.iterrows():
            date = row["Date"]
            if not pd.isna(row.get("Shares Bought", float("nan"))):
                buy_queue.append({"date": date, "shares": float(row["Shares Bought"])})
            if not pd.isna(row.get("Shares Sold", float("nan"))):
                shares_to_sell = float(row["Shares Sold"])
                while shares_to_sell > 1e-9 and buy_queue:
                    buy = buy_queue[0]
                    matched = min(buy["shares"], shares_to_sell)
                    days = (date - buy["date"]).days
                    holding_days.append(days)
                    buy["shares"] -= matched
                    shares_to_sell -= matched
                    if buy["shares"] < 1e-9:
                        buy_queue.pop(0)
    return sorted(holding_days)


def eval():
    pred_path = "pred_results/pred_holding_distribution.png"

    # Step 1: Check predicted file exists
    if not os.path.exists(pred_path):
        return (False, "Predicted output file not found at pred_results/pred_holding_distribution.png")

    # Step 2: Validate the predicted image is a valid PNG
    try:
        pred_img = Image.open(pred_path)
        pred_img.load()
    except Exception as e:
        return (False, f"Predicted file is not a valid image: {e}")

    # Step 3: Check DPI - allow some tolerance (250-350)
    pred_dpi = pred_img.info.get("dpi", (None, None))
    if pred_dpi and pred_dpi[0] is not None:
        if not (250 <= pred_dpi[0] <= 350):
            return (False, f"Predicted image DPI is {pred_dpi[0]}, expected ~300 (acceptable range: 250-350)")

    # Step 4: Check image has reasonable dimensions (not too small)
    if pred_img.size[0] < 100 or pred_img.size[1] < 100:
        return (False, f"Predicted image is too small: {pred_img.size}")

    # Step 5: Check image is not blank
    pred_arr = np.array(pred_img.convert("RGB"))
    white_ratio = np.mean(pred_arr > 240)
    if white_ratio > 0.98:
        return (False, "Predicted image appears to be nearly blank (>98% white pixels)")

    # Step 6: Recompute FIFO holding days from source data
    try:
        gold_holding_days = compute_fifo_holding_days()
    except Exception as e:
        return (False, f"Failed to recompute FIFO holding days: {e}")

    if len(gold_holding_days) == 0:
        return (False, "No holding periods computed from the dataset")

    # Step 7: Verify all holding periods are non-negative
    if any(d < 0 for d in gold_holding_days):
        return (False, "Negative holding periods detected - FIFO computation error")

    # Step 8: Verify the image contains a histogram-like distribution
    # Check that the image has meaningful variation (not uniform color)
    pred_gray = np.mean(pred_arr.astype(float), axis=2)
    if np.std(pred_gray) < 5.0:
        return (False, f"Predicted image has very low variation (std={np.std(pred_gray):.2f}), may not contain a valid plot")

    # Step 9: Check that the image has non-trivial content (dark pixels for bars/axes)
    dark_pixel_ratio = np.mean(pred_arr < 100)
    if dark_pixel_ratio < 0.001:
        return (False, "Predicted image has very few dark pixels - likely missing histogram bars or axes")

    # Step 10: Verify basic statistics of the computed holding periods are reasonable
    gold_array = np.array(gold_holding_days)
    min_days = gold_array.min()
    max_days = gold_array.max()
    mean_days = gold_array.mean()
    n_periods = len(gold_array)

    # Sanity checks on the holding periods
    if n_periods < 1:
        return (False, "Too few holding periods computed")

    if min_days < 0:
        return (False, f"Minimum holding period is negative: {min_days}")

    if max_days > 3650:  # More than 10 years seems unreasonable
        return (False, f"Maximum holding period seems unreasonably large: {max_days} days")

    # Step 11: Verify the image dimensions are reasonable for a histogram plot
    # A typical matplotlib figure at 300 DPI should be at least 800x400 pixels
    width, height = pred_img.size
    if width < 400 or height < 300:
        return (False, f"Image dimensions {pred_img.size} seem too small for a proper histogram plot")

    # Step 12: Check that the image has the right aspect ratio (roughly landscape)
    aspect_ratio = width / height
    if aspect_ratio < 0.5 or aspect_ratio > 4.0:
        return (False, f"Image aspect ratio {aspect_ratio:.2f} seems unusual for a histogram plot")

    return (
        True,
        f"Evaluation passed. "
        f"Image is valid PNG at {pred_dpi} DPI with dimensions {pred_img.size}. "
        f"FIFO computation yields {n_periods} holding periods. "
        f"Holding period stats: min={min_days}d, max={max_days}d, mean={mean_days:.1f}d. "
        f"Image has {white_ratio:.1%} white pixels and {dark_pixel_ratio:.1%} dark pixels."
    )


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")---
