def parse_results(filepath):
    """Parse key-value results file. Returns dict of {key: value_string}."""
    data = {}
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if ':' in line:
                key, _, val = line.partition(':')
                data[key.strip()] = val.strip()
    return data


def compute_reference_energy():
    """Compute reference energy using PySCF directly."""
    try:
        mol = gto.M(atom='Li 0 0 0', basis='sto-3g', spin=1, charge=0, verbose=0)
        mf = scf.UKS(mol)
        mf.xc = 'lda,pw'
        mf.run()
        return mf.e_tot
    except Exception:
        return None


