        newton_energy = float(pred['newton_scf_energy'])
    except (KeyError, ValueError) as e:
        return (False, f"Missing or invalid energy values: {e}")

    ref_energy = compute_reference_energy()
    if ref_energy is None:
        return (False, "Failed to compute PySCF reference energy")

