import os
import pandas as pd
from PIL import Image


def eval():
    pred_csv = "pred_results/pred_repeated_ticker_exposure.csv"
    pred_png = "pred_results/pred_repeated_ticker_exposure.png"
    gold_csv = "./gold_results/pred_repeated_ticker_exposure.csv"
    gold_png = "./gold_results/pred_repeated_ticker_exposure.png"

    # Step 1: Check existence of predicted output files
    for f in [pred_csv, pred_png]:
        if not os.path.exists(f):
            return (False, f"Missing predicted output file: {f}")

    for f in [gold_csv, gold_png]:
        if not os.path.exists(f):
            return (False, f"Missing gold result file: {f}")

    # Step 2: Validate PNG is a readable image
    try:
        img = Image.open(pred_png)
        img.verify()
        img = Image.open(pred_png)  # Re-open after verify (verify closes the file)
        w, h = img.size
        if w < 100 or h < 100:
            return (False, f"Predicted PNG image too small: {w}x{h}")
    except Exception as e:
        return (False, f"Predicted PNG is not a valid image: {e}")

    # Step 3: Load and compare CSV data
    try:
        pred_df = pd.read_csv(pred_csv)
    except Exception as e:
        return (False, f"Failed to read predicted CSV: {e}")

    try:
        gold_df = pd.read_csv(gold_csv)
    except Exception as e:
        return (False, f"Failed to read gold CSV: {e}")

    # Validate predicted CSV has at least 2 columns (ticker + count, possibly more)
    if len(pred_df.columns) < 2:
        return (False, f"Expected at least 2 columns in predicted CSV, got {len(pred_df.columns)}: {list(pred_df.columns)}")

    # Identify ticker column - look for column named 'Ticker' or similar
    pred_ticker_col = None
    for col in pred_df.columns:
        if col.strip().lower() in ['ticker', 'symbol', 'stock']:
            pred_ticker_col = col
            break
    if pred_ticker_col is None:
        # Fall back to first column
        pred_ticker_col = pred_df.columns[0]

    # Identify re-entry count column - look for column with 're-entr', 'reentr', 'count', 'entries' in name
    pred_count_col = None
    count_keywords = ['re-entr', 'reentr', 're_entr', 'count', 'entries', 'entry', 'frequency']
    for col in pred_df.columns:
        col_lower = col.strip().lower()
        for kw in count_keywords:
            if kw in col_lower:
                pred_count_col = col
                break
        if pred_count_col is not None:
            break

    if pred_count_col is None:
        # Fall back to last numeric column that isn't the ticker column
        for col in reversed(pred_df.columns):
            if col != pred_ticker_col and pd.api.types.is_numeric_dtype(pred_df[col]):
                pred_count_col = col
                break

    if pred_count_col is None:
        # Fall back to second column
        pred_count_col = pred_df.columns[1] if len(pred_df.columns) > 1 else pred_df.columns[0]

    # Identify gold columns (assume first=ticker, second=count)
    gold_ticker_col = gold_df.columns[0]
    gold_count_col = gold_df.columns[1]

    # Clean data
    pred_tickers = pred_df[pred_ticker_col].astype(str).str.strip().str.upper()
    gold_tickers = gold_df[gold_ticker_col].astype(str).str.strip().str.upper()

    pred_counts = pd.to_numeric(pred_df[pred_count_col], errors="coerce").fillna(0).astype(int)
    gold_counts = pd.to_numeric(gold_df[gold_count_col], errors="coerce").fillna(0).astype(int)

    # Build dicts of ticker -> count
    pred_dict = dict(zip(pred_tickers, pred_counts))
    gold_dict = dict(zip(gold_tickers, gold_counts))

    # Focus on tickers with non-zero re-entries in gold (the important ones)
    gold_nonzero = {k: v for k, v in gold_dict.items() if v > 0}
    pred_nonzero = {k: v for k, v in pred_dict.items() if v > 0}

    # Check that all tickers with re-entries in gold are present with correct counts
    missing_tickers = []
    wrong_counts = []
    for ticker, gold_count in gold_nonzero.items():
        if ticker not in pred_nonzero:
            missing_tickers.append(ticker)
        elif pred_nonzero[ticker] != gold_count:
            wrong_counts.append(
                f"{ticker}: expected {gold_count}, got {pred_nonzero[ticker]}"
            )

    if missing_tickers:
        return (False, f"Missing tickers with re-entries: {missing_tickers}")

    if wrong_counts:
        return (False, f"Incorrect re-entry counts: {'; '.join(wrong_counts)}")

    # Check for false positives (pred says non-zero but gold says zero or absent)
    extra_nonzero = []
    for ticker, pred_count in pred_nonzero.items():
        gold_count = gold_dict.get(ticker, 0)
        if gold_count == 0:
            extra_nonzero.append(f"{ticker}: predicted {pred_count} but gold is 0")

    if extra_nonzero:
        return (False, f"Extra tickers with non-zero re-entries: {'; '.join(extra_nonzero)}")

