def _find_csv(directory):
    """Find the pred_main_*.csv file in a directory."""
    pattern = os.path.join(directory, "pred_main_*.csv")
    matches = glob.glob(pattern)
    if matches:
        return matches[0]
    # Fallback: any csv
    pattern2 = os.path.join(directory, "*.csv")
    matches2 = glob.glob(pattern2)
    if matches2:
        return matches2[0]
    return None


def _load_csv(path):
    """Load CSV and return list of dicts and fieldnames."""
    with open(path, "r", newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)
        return rows, reader.fieldnames


