        echo "  shell         Start an interactive shell"
        echo "  help          Show this message"
        echo ""
        echo "Example:"
        echo "  docker run -v ./my_solution.py:/task/solution.py -v ./my_results:/task/pred_results <​image> run_and_eval"
        ;;
esac
"}

