import pandas as pd
import os


def eval():
    pred_path = "pred_results/pred_add_extra_sample_metadata.tsv"
    gold_path = "./gold_results/pred_add_extra_sample_metadata.tsv"

    # Check files exist
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")
    if not os.path.exists(gold_path):
        return (False, f"Gold result file not found: {gold_path}")

    # Load both files
    try:
        pred = pd.read_csv(pred_path, sep='\t')
    except Exception as e:
        return (False, f"Failed to parse predicted TSV file: {e}")

    try:
        gold = pd.read_csv(gold_path, sep='\t')
    except Exception as e:
        return (False, f"Failed to parse gold TSV file: {e}")

    # Step 1: Check shape matches
    if pred.shape[0] != gold.shape[0]:
        return (False, f"Row count mismatch: predicted {pred.shape[0]} vs gold {gold.shape[0]}")

    # Step 2: Check all expected columns are present
    missing_cols = set(gold.columns) - set(pred.columns)
    if missing_cols:
        return (False, f"Missing columns in predicted output: {missing_cols}")

    extra_cols = set(pred.columns) - set(gold.columns)
    if extra_cols:
        return (False, f"Unexpected extra columns in predicted output: {extra_cols}")

    # Step 3: Check column order matches
    if list(pred.columns) != list(gold.columns):
        return (False, f"Column order mismatch. Expected: {list(gold.columns)}, Got: {list(pred.columns)}")

    # Step 4: Check experiment_id column exists and matches
    if 'experiment_id' not in pred.columns:
        return (False, "experiment_id column missing from predicted output")

    pred_sorted = pred.sort_values('experiment_id').reset_index(drop=True)
    gold_sorted = gold.sort_values('experiment_id').reset_index(drop=True)

    if set(pred_sorted['experiment_id']) != set(gold_sorted['experiment_id']):
        return (False, "experiment_id values do not match between predicted and gold")

    # Step 5: Check all data values match
    # Fill NaN with empty string for comparison since TSV may have empty fields
    pred_filled = pred_sorted.fillna('')
    gold_filled = gold_sorted.fillna('')

    for col in gold.columns:
        pred_vals = pred_filled[col].astype(str).tolist()
        gold_vals = gold_filled[col].astype(str).tolist()
        if pred_vals != gold_vals:
            mismatches = [(i, p, g) for i, (p, g) in enumerate(zip(pred_vals, gold_vals)) if p != g]
            first = mismatches[0]
            return (False, f"Data mismatch in column '{col}' at row {first[0]}: predicted='{first[1]}' vs gold='{first[2]}'")

    # Step 6: Verify no all-NaN columns exist
    all_nan_cols = [c for c in pred.columns if pred[c].isna().all()]
    if all_nan_cols:
        return (False, f"Columns with all missing values found: {all_nan_cols}")

    return (True, "All checks passed: correct shape, columns, data values, and format")


