    gold_counts = pd.to_numeric(gold_df[gold_count_col], errors="coerce").fillna(0).astype(int)

    # Build dicts of ticker -> count
    pred_dict = dict(zip(pred_tickers, pred_counts))
    gold_dict = dict(zip(gold_tickers, gold_counts))

    # Focus on tickers with non-zero re-entries in gold (the important ones)
    gold_nonzero = {k: v for k, v in gold_dict.items() if v > 0}
    pred_nonzero = {k: v for k, v in pred_dict.items() if v > 0}

    # Check that all tickers with re-entries in gold are present with correct counts
    missing_tickers = []
    wrong_counts = []
    for ticker, gold_count in gold_nonzero.items():
        if ticker not in pred_nonzero:
            missing_tickers.append(ticker)
        elif pred_nonzero[ticker] != gold_count:
            wrong_counts.append(
                f"{ticker}: expected {gold_count}, got {pred_nonzero[ticker]}"
            )

    if missing_tickers:
        return (False, f"Missing tickers with re-entries: {missing_tickers}")

    if wrong_counts:
        return (False, f"Incorrect re-entry counts: {'; '.join(wrong_counts)}")

    # Check for false positives (pred says non-zero but gold says zero or absent)
    extra_nonzero = []
    for ticker, pred_count in pred_nonzero.items():
        gold_count = gold_dict.get(ticker, 0)
        if gold_count == 0:
            extra_nonzero.append(f"{ticker}: predicted {pred_count} but gold is 0")

    if extra_nonzero:
        return (False, f"Extra tickers with non-zero re-entries: {'; '.join(extra_nonzero)}")

    # Step 4: Verify sorting (should be descending by count) - informational only, not failing
    pred_counts_list = pred_df[pred_count_col].tolist()
    is_sorted = pred_counts_list == sorted(pred_counts_list, reverse=True)

    sort_note = "" if is_sorted else " (Note: data not sorted in descending order)"

