import json
import os


def eval():
    pred_path = "pred_results/pred_PUKnn.json"

    # Check file exists
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")

    # Load JSON file
    try:
        with open(pred_path, 'r') as f:
            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as e:
        return (False, f"Failed to parse predicted JSON: {e}")

    errors = []

    # Helper function to search for a value in nested dict
    def find_value(d, keys, default=None):
        """Search for a key in a nested dict, trying multiple possible key names."""
        if not isinstance(d, dict):
            return default
        for key in keys:
            if key in d:
                val = d[key]
                if isinstance(val, dict):
                    continue
                return val
        # Search recursively
        for v in d.values():
            if isinstance(v, dict):
                result = find_value(v, keys, None)
                if result is not None:
                    return result
        return default

    def find_nested(d, keys, default=None):
        """Search for any of the given keys at any nesting level."""
        if not isinstance(d, dict):
            return default
        for key in keys:
            if key in d:
                return d[key]
        for v in d.values():
            if isinstance(v, dict):
                result = find_nested(v, keys, None)
                if result is not None:
                    return result
        return default

    # Check 1: Validate train/val sample counts
    # Look for train samples count with various possible key names
    train_samples = find_nested(pred, [
        "num_samples_train", "train_samples", "train_size", 
        "training_samples", "n_train", "num_train"
    ])

    val_samples = find_nested(pred, [
        "num_samples_val", "val_samples", "validation_samples",
        "val_size", "n_val", "num_val"
    ])

    if train_samples is None:
        errors.append("Missing train sample count (looked for: num_samples_train, train_samples, etc.)")
    elif abs(int(train_samples) - 104) > 2:
        errors.append(f"train_samples should be ~104 (80% of 130), got {train_samples}")

    if val_samples is None:
        errors.append("Missing validation sample count (looked for: num_samples_val, val_samples, etc.)")
    elif abs(int(val_samples) - 26) > 2:
        errors.append(f"val_samples should be ~26 (20% of 130), got {val_samples}")

    # Check total is 130
    if train_samples is not None and val_samples is not None:
        total = int(train_samples) + int(val_samples)
        if total != 130:
            errors.append(f"Total samples (train + val) should be 130, got {total}")

    # Check 2: Feature dimensions should be 1024
    feature_dim = find_nested(pred, [
        "feature_dimensions", "feature_dimension", "feature_dim",
        "num_features", "input_dim", "node_features_dim"
    ])

    if feature_dim is None:
        errors.append("Missing feature dimension info (looked for: feature_dimensions, feature_dimension, etc.)")
    elif int(feature_dim) != 1024:
        errors.append(f"feature_dimensions should be 1024, got {feature_dim}")

    # Check 3: Class labels should be present
    class_labels = find_nested(pred, [
        "class_labels", "labels", "classes", "unique_labels",
        "num_classes", "n_classes"
    ])

    if class_labels is None:
        errors.append("Missing class labels info (looked for: class_labels, labels, classes, etc.)")
    else:
        if isinstance(class_labels, list):
            # Should have 13 classes (0-12 or strings)
            if len(class_labels) != 13:
                errors.append(f"Expected 13 class labels, got {len(class_labels)}")
        elif isinstance(class_labels, int):
            if class_labels != 13:
                errors.append(f"Expected 13 classes, got {class_labels}")

    # Check 4: Working condition should be mentioned
    working_condition = find_nested(pred, [
        "working_condition", "condition", "operating_condition"
    ])

    # Also check if it appears as a string value anywhere in the dict
    pred_str = json.dumps(pred)
    if "N15_M07_F10" not in pred_str:
        # Not a hard failure, but note it
        pass  # Working condition check is optional

    # Check 5: K neighbors parameter should be 10
    k_neighbors = find_nested(pred, [
        "k_neighbors", "k", "num_neighbors", "n_neighbors",
        "knn_k", "neighbors"
    ])

    if k_neighbors is not None:
        if int(k_neighbors) != 10:
            errors.append(f"k_neighbors should be 10, got {k_neighbors}")
    # k_neighbors check is optional - not all implementations may store this

    # Check 6: Split percentages should reflect 80/20 split
    train_pct = find_nested(pred, [
        "train_percentage", "train_ratio", "train_split"
    ])
    val_pct = find_nested(pred, [
        "val_percentage", "val_ratio", "val_split"
    ])

    if train_pct is not None and val_pct is not None:
        if abs(float(train_pct) - 80) > 1 and abs(float(train_pct) - 0.8) > 0.01:
            errors.append(f"train_percentage should be 80 (or 0.8), got {train_pct}")

    # Check 7: Window size should be 1024
    window_size = find_nested(pred, [
        "window_size", "window_size_samples", "sample_length",
        "segment_length", "window_length"
    ])

    if window_size is not None:
        if int(window_size) != 1024:
            errors.append(f"window_size should be 1024, got {window_size}")

    if errors:
        return (False, "; ".join(errors))

    return (True, f"All checks passed: correct split sizes (train={train_samples}, val={val_samples}), "
                  f"feature dimensions ({feature_dim}), class labels present, and processing parameters.")


