import os
import pandas as pd
from PIL import Image
import matplotlib.pyplot as plt
import matplotlib.image as mpimg
import numpy as np


def eval():
    pred_path = "pred_results/return_by_trades.png"
    gold_path = "./gold_results/return_by_trades.png"
    trade_log_path = "benchmark/datasets/LLM-Trading-Lab/Experiments/chatgpt_micro-cap/csv_files/Trade Log.csv"

    # Step 1: Check predicted file exists and is valid PNG
    if not os.path.exists(pred_path):
        return (False, "Predicted output file 'pred_results/return_by_trades.png' does not exist.")

    file_size = os.path.getsize(pred_path)
    if file_size < 1024:
        return (False, f"Predicted PNG file is too small ({file_size} bytes), expected >1KB.")

    try:
        img = Image.open(pred_path)
        img.verify()
    except Exception as e:
        return (False, f"Predicted file is not a valid image: {e}")

    # Step 2: Check gold file exists
    if not os.path.exists(gold_path):
        return (False, "Gold result file not found at expected path.")

    try:
        gold_img = Image.open(gold_path)
        gold_img.verify()
    except Exception as e:
        return (False, f"Gold file is not a valid image: {e}")

    # Step 3: Compute expected PnL aggregation from source data
    try:
        trades = pd.read_csv(trade_log_path)
    except Exception as e:
        return (False, f"Could not load Trade Log CSV: {e}")

    realized = trades.dropna(subset=["Shares Sold", "Sell Price", "PnL"])
    expected_pnl = realized.groupby("Ticker")["PnL"].sum().sort_values(ascending=False)

    expected_tickers = list(expected_pnl.index)
    expected_values = list(expected_pnl.values)

    # Step 4: Compare predicted image against gold image using pixel similarity
    # Reload images for comparison
    try:
        pred_img_arr = mpimg.imread(pred_path)
        gold_img_arr = mpimg.imread(gold_path)
    except Exception as e:
        return (False, f"Could not read images for comparison: {e}")

    # Check that images have similar dimensions (allow some tolerance for DPI differences)
    pred_h, pred_w = pred_img_arr.shape[:2]
    gold_h, gold_w = gold_img_arr.shape[:2]

    # If dimensions differ significantly, the visualization is likely wrong
    dim_ratio_h = pred_h / gold_h if gold_h > 0 else 0
    dim_ratio_w = pred_w / gold_w if gold_w > 0 else 0

    if dim_ratio_h < 0.3 or dim_ratio_h > 3.0 or dim_ratio_w < 0.3 or dim_ratio_w > 3.0:
        return (False, f"Image dimensions differ significantly: pred ({pred_w}x{pred_h}) vs gold ({gold_w}x{gold_h}).")

    # Step 5: For a more robust check, regenerate the expected chart and compare
    # We verify the predicted image is reasonable by checking it's not blank/trivial
    pred_img_full = Image.open(pred_path)
    pred_arr = np.array(pred_img_full)

    # Check the image is not all white or all one color (trivial image)
    if pred_arr.ndim >= 3:
        color_std = np.std(pred_arr[:, :, :3].astype(float))
    else:
        color_std = np.std(pred_arr.astype(float))

    if color_std < 5.0:
        return (False, "Predicted image appears to be blank or trivially uniform.")

    # Step 6: Compare pixel similarity between predicted and gold
    # Resize both to same dimensions for comparison
    from PIL import Image as PILImage
    common_size = (800, 600)
    pred_resized = np.array(PILImage.open(pred_path).convert("RGB").resize(common_size, PILImage.LANCZOS)).astype(float)
    gold_resized = np.array(PILImage.open(gold_path).convert("RGB").resize(common_size, PILImage.LANCZOS)).astype(float)

    # Compute normalized mean absolute error
    mae = np.mean(np.abs(pred_resized - gold_resized)) / 255.0

    # Allow some tolerance for rendering differences (fonts, anti-aliasing, etc.)
    # A very similar chart should have MAE < 0.15
    if mae < 0.15:
        return (True, f"Visualization matches gold standard. Image MAE: {mae:.4f}.")

    # If pixel comparison is not close enough, do a structural check
    # This handles cases where the chart is correct but rendered slightly differently

    # Step 7: Verify the number of bars by checking unique colored regions
    # We check that the image has sufficient non-white content (bars exist)
    white_threshold = 240
    if pred_resized.ndim == 3:
        non_white_mask = np.any(pred_resized < white_threshold, axis=2)
    else:
        non_white_mask = pred_resized < white_threshold

    non_white_fraction = np.mean(non_white_mask)

    if non_white_fraction < 0.05:
        return (False, "Predicted image has insufficient content - likely missing bars.")

    # Step 8: Additional lenient comparison - if the images are somewhat similar
    # and basic structural checks pass, accept it
    # Check that predicted image has similar amount of colored content as gold
    if gold_resized.ndim == 3:
        gold_non_white = np.any(gold_resized < white_threshold, axis=2)
    else:
        gold_non_white = gold_resized < white_threshold

    gold_non_white_fraction = np.mean(gold_non_white)
    content_ratio = non_white_fraction / gold_non_white_fraction if gold_non_white_fraction > 0 else 0

    # The amount of non-white content should be in a reasonable range
    if content_ratio < 0.4 or content_ratio > 2.5:
        return (False, f"Predicted image content differs significantly from gold. Content ratio: {content_ratio:.2f}, MAE: {mae:.4f}.")

    # If MAE is moderate and structural checks pass, accept with note
    if mae < 0.35:
        return (True, f"Visualization is acceptably similar to gold standard. Image MAE: {mae:.4f}.")

    return (False, f"Visualization differs too much from gold standard. Image MAE: {mae:.4f}.")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")---
