    try:
        fasta_entries = parse_fasta(fasta_path)
    except Exception as e:
        return (False, f"Error parsing FASTA file: {e}")

    if not fasta_entries:
        return (False, "No entries found in FASTA file")

    # Build ground truth lookup
    gold_by_id = {entry_id: seq for entry_id, seq in fasta_entries}

