import json
import os


def parse_fasta(fasta_path):
    """Parse a FASTA file and return list of (identifier, sequence) tuples."""
    entries = []
    current_id = None
    current_seq = []

    with open(fasta_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('>'):
                if current_id is not None:
                    entries.append((current_id, ''.join(current_seq)))
                    current_seq = []
                current_id = line[1:]
            else:
                current_seq.append(line)

    if current_id is not None and current_seq:
        entries.append((current_id, ''.join(current_seq)))

    return entries


def eval():
    pred_path = "pred_results/pred_datasets.json"
    fasta_path = "benchmark/datasets/tape/tape/example.fasta"

    # Check predicted file exists
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")

    # Check source FASTA file exists
    if not os.path.exists(fasta_path):
        return (False, f"Source FASTA file not found: {fasta_path}")

    # Load and parse predicted JSON
    try:
        with open(pred_path) as f:
            pred_data = json.load(f)
    except json.JSONDecodeError as e:
        return (False, f"Predicted file is not valid JSON: {e}")

    # Validate structure is a list
    if not isinstance(pred_data, list):
        return (False, f"Predicted JSON is not a list, got {type(pred_data).__name__}")

    # Parse the source FASTA file to get ground truth
    try:
        fasta_entries = parse_fasta(fasta_path)
    except Exception as e:
        return (False, f"Failed to parse FASTA file: {e}")

    # Check completeness - number of entries
    if len(pred_data) != len(fasta_entries):
        return (False, f"Entry count mismatch: predicted {len(pred_data)}, expected {len(fasta_entries)}")

    def get_fields(entry):
        """Extract (identifier, sequence, length) from an entry, accepting multiple field name conventions."""
        id_val = entry.get("id") or entry.get("identifier")
        seq_val = entry.get("primary") or entry.get("sequence")
        len_val = entry.get("protein_length") or entry.get("length")
        return id_val, seq_val, len_val

    # Build gold lookup by identifier from FASTA
    gold_by_id = {}
    for fasta_id, fasta_seq in fasta_entries:
        gold_by_id[fasta_id] = fasta_seq

    # Also build lookup by just the first part of the identifier (before whitespace)
    gold_by_short_id = {}
    for fasta_id, fasta_seq in fasta_entries:
        short_id = fasta_id.split()[0]
        gold_by_short_id[short_id] = (fasta_id, fasta_seq)

    # Validate each predicted entry
    matched = 0
    for i, p in enumerate(pred_data):
        if not isinstance(p, dict):
            return (False, f"Predicted entry {i} is not a dict")

        p_id, p_seq, p_len = get_fields(p)

        if p_id is None:
            return (False, f"Predicted entry {i} missing identifier field (expected 'id' or 'identifier')")
        if p_seq is None:
            return (False, f"Predicted entry {i} missing sequence field (expected 'primary' or 'sequence')")
        if p_len is None:
            return (False, f"Predicted entry {i} missing length field (expected 'protein_length' or 'length')")

        # Validate length is an integer
        try:
            p_len_int = int(p_len)
        except (ValueError, TypeError):
            return (False, f"Predicted entry {i} has non-integer length: {p_len}")

        # Validate length matches actual sequence length
        if p_len_int != len(p_seq):
            return (False, f"Predicted entry {i} ({p_id}): length field ({p_len_int}) != actual sequence length ({len(p_seq)})")

        # Try to find matching gold entry (full id or short id)
        gold_seq = None
        if p_id in gold_by_id:
            gold_seq = gold_by_id[p_id]
        elif p_id in gold_by_short_id:
            gold_seq = gold_by_short_id[p_id][1]
        else:
            # Try matching by short id from the predicted id
            p_short_id = p_id.split()[0]
            if p_short_id in gold_by_short_id:
                gold_seq = gold_by_short_id[p_short_id][1]

        if gold_seq is None:
            return (False, f"Predicted entry {i} has identifier '{p_id}' not found in FASTA file")

        # Validate sequence matches
        if p_seq != gold_seq:
            return (False, f"Sequence mismatch for '{p_id}': predicted length {len(p_seq)}, expected length {len(gold_seq)}")

        # Validate length matches gold sequence length
        if p_len_int != len(gold_seq):
            return (False, f"Length mismatch for '{p_id}': predicted {p_len_int}, expected {len(gold_seq)}")

        matched += 1

    if matched != len(fasta_entries):
        return (False, f"Only {matched}/{len(fasta_entries)} entries matched")

    return (True, f"All {matched} protein entries correctly extracted with matching identifiers, sequences, and lengths")


