    # Check for RASTA filtering enabled
    has_rasta = False
    if 'rasta' in props_lower:
        for indicator in ['true', 'enabled', 'yes', 'on', '1']:
            if indicator in props_lower:
                has_rasta = True
                break
    if not has_rasta:
        return (False, "Properties file does not indicate RASTA filtering is enabled")

