    ])

    if not has_dimensions:
        return (False, "Properties file missing feature dimension information")
    if not has_sampling:
        return (False, "Properties file missing sampling parameter information")

    # 10. Compare with gold standard if available
    gold_available = os.path.isfile(gold_csv)
