def normalize_text(text):
    """Normalize text for flexible matching - lowercase, replace underscores/hyphens with spaces."""
    if isinstance(text, str):
        return text.lower().replace('_', ' ').replace('-', ' ')
    return str(text).lower()


def json_to_normalized_string(d):
    """Convert JSON to normalized string for flexible searching."""
    raw = json.dumps(d, ensure_ascii=False)
    return normalize_text(raw)


def find_in_json_values(d, target_str, case_insensitive=True):
    """Recursively search all values in a JSON structure for a string."""
    target = target_str.lower() if case_insensitive else target_str

    if isinstance(d, dict):
        for k, v in d.items():
            if find_in_json_values(v, target_str, case_insensitive):
                return True
    elif isinstance(d, list):
        for item in d:
            if find_in_json_values(item, target_str, case_insensitive):
                return True
    elif isinstance(d, str):
        val = d.lower() if case_insensitive else d
        if target in val:
