    pred_dir = "pred_results/"

    # Step 1: Discover predicted files - look for any matching pattern
    pred_jsons = glob.glob(os.path.join(pred_dir, "pred_vis_other_explainer_*.json"))

    if not pred_jsons:
        return (False, "No predicted JSON files found matching pattern 'pred_vis_other_explainer_*.json' in pred_results directory.")

    # Check that at least one valid pair exists
    valid_pairs = []
    for pred_json_path in pred_jsons:
        basename = os.path.basename(pred_json_path)
        png_basename = basename.replace(".json", ".png")
        pred_png_path = os.path.join(pred_dir, png_basename)

        if os.path.exists(pred_png_path):
            valid_pairs.append((pred_json_path, pred_png_path, basename, png_basename))

    if not valid_pairs:
        return (False, f"Found JSON files but no matching PNG files. JSON files found: {[os.path.basename(p) for p in pred_jsons]}")

    # Validate each pair
    for pred_json_path, pred_png_path, basename, png_basename in valid_pairs:

        # Step 2: Validate PNG file size (>5KB for meaningful visualization)
        png_size = os.path.getsize(pred_png_path)
        if png_size < 5000:
            return (False, f"PNG file {png_basename} is too small ({png_size} bytes), expected >5KB for a meaningful visualization.")

        # Validate PNG is a valid image (check PNG magic bytes)
        with open(pred_png_path, "rb") as f:
            header = f.read(8)
        if header[:4] != b"\x89PNG":
            return (False, f"File {png_basename} is not a valid PNG image.")

        # Step 3: Load and validate predicted JSON
        try:
            with open(pred_json_path, "r") as f:
                pred_data = json.load(f)
        except (json.JSONDecodeError, Exception) as e:
            return (False, f"Failed to parse predicted JSON {basename}: {e}")

        # Step 4: Check required keys
        required_keys = ["true_labels", "predictions", "sample_indices"]
        for key in required_keys:
            if key not in pred_data:
                return (False, f"Missing required key '{key}' in predicted JSON {basename}.")

        # Step 5: Check exactly 3 samples
        for key in required_keys:
            if not isinstance(pred_data[key], list):
                return (False, f"Key '{key}' should be a list, got {type(pred_data[key]).__name__}.")
            if len(pred_data[key]) != 3:
                return (False, f"Key '{key}' should have exactly 3 entries, got {len(pred_data[key])}.")

        # Step 6: Validate data types - sample indices should be integers
        for idx in pred_data["sample_indices"]:
            if not isinstance(idx, (int, float)):
                return (False, f"Sample index {idx} is not a valid number.")
            if isinstance(idx, float) and idx != int(idx):
                return (False, f"Sample index {idx} is not a valid integer.")

        # Step 7: Validate true labels are numbers
        for label in pred_data["true_labels"]:
            if not isinstance(label, (int, float)):
                return (False, f"True label {label} is not a valid number.")

        # Step 8: Validate predictions are numbers
        for pred in pred_data["predictions"]:
            if not isinstance(pred, (int, float)):
                return (False, f"Prediction {pred} is not a valid number.")

        # Step 9: Check that sample indices are unique
        indices = [int(idx) for idx in pred_data["sample_indices"]]
        if len(set(indices)) != len(indices):
            return (False, f"Sample indices should be unique, got {pred_data['sample_indices']}.")

        # Step 10: Check filename contains dataset and method info
        # The filename should be pred_vis_other_explainer_{dataset}_{exp_method}
        name_without_ext = basename.replace(".json", "")
        parts = name_without_ext.replace("pred_vis_other_explainer_", "")
        if not parts or "_" not in parts:
            return (False, f"Filename {basename} doesn't seem to contain both dataset and method info.")

