PRED_DIR = "pred_results"
GOLD_DIR = "./gold_results/"

REQUIRED_FILES = ["pred_ukb_navigator.txt", "report.md", "matched_fields.csv"]

RELEVANCE_KEYWORDS = [
    "blood pressure", "bp", "hypertension", "systolic", "diastolic",
    "cardiovascular", "antihypertensive", "arterial pressure",
    "vascular", "heart", "medication", "icd", "mmhg",
]


def eval():
    # Step 1: Verify all required files exist and are non-empty
    for fname in REQUIRED_FILES:
        pred_path = os.path.join(PRED_DIR, fname)
        if not os.path.exists(pred_path):
            return (False, f"Missing required file: {pred_path}")
        if os.path.getsize(pred_path) == 0:
            return (False, f"File is empty: {pred_path}")

    # Step 2: Validate CSV structure
    pred_csv_path = os.path.join(PRED_DIR, "matched_fields.csv")

    try:
        with open(pred_csv_path, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            pred_fieldnames = reader.fieldnames
            pred_rows = list(reader)
    except Exception as e:
        return (False, f"Failed to parse predicted CSV: {e}")

    if pred_fieldnames is None or len(pred_fieldnames) == 0:
        return (False, "Predicted CSV has no columns")

    # Check that predicted CSV has a similarity column (name may vary)
    sim_col = None
    for col in pred_fieldnames:
        if "similar" in col.lower() or "score" in col.lower() or "distance" in col.lower():
            sim_col = col
            break

    # Also check for a text/description column
    text_col = None
    for col in pred_fieldnames:
        if any(kw in col.lower() for kw in ["text", "description", "field", "desc"]):
            text_col = col
            break

    if len(pred_rows) < 3:
        return (False, f"Predicted CSV has only {len(pred_rows)} data rows, expected at least 3")

    # Step 3: Check similarity score ordering (if similarity column found)
    if sim_col:
        try:
            scores = [float(row[sim_col]) for row in pred_rows]
        except (ValueError, KeyError) as e:
            return (False, f"Non-numeric similarity scores: {e}")

        for i in range(len(scores) - 1):
            if scores[i] < scores[i + 1]:
                return (False, f"Similarity scores not in descending order: {scores[i]} < {scores[i+1]} at rows {i+1},{i+2}")

    # Step 4: Relevance heuristic check
    # Gather all text content from the CSV rows for relevance checking
    def get_row_text(row):
        return " ".join(str(v) for v in row.values()).lower()

    top_n = min(10, len(pred_rows))
    relevant_count = 0
    for row in pred_rows[:top_n]:
        row_text = get_row_text(row)
        if any(kw in row_text for kw in RELEVANCE_KEYWORDS):
            relevant_count += 1

    relevance_pct = relevant_count / top_n
    if relevance_pct < 0.50:
        return (False, f"Only {relevant_count}/{top_n} top results are relevant to blood pressure/hypertension ({relevance_pct:.0%} < 50%)")

    # Step 5: Validate report.md content
