import sys

def eval():
    pred_file = "pred_results/pred_sascorer.txt"
    gold_file = "gold_results/pred_sascorer.txt"

    if not os.path.exists(pred_file):
        return False, f"Prediction file not found: {pred_file}"

    if not os.path.exists(gold_file):
        return False, f"Gold file not found: {gold_file}"

    try:
        with open(pred_file) as f:
            pred_lines = f.read().strip().splitlines()
        with open(gold_file) as f:
            gold_lines = f.read().strip().splitlines()
    except Exception as e:
        return False, f"Error reading files: {e}"

    if len(pred_lines) < 2:
        return False, "Prediction file has no data rows"

    pred_header = pred_lines[0].split("\t")
    expected_cols = ["smiles", "Name", "sa_score"]
    for col in expected_cols:
        if col not in pred_header:
            return False, f"Missing column '{col}' in prediction header. Got: {pred_header}"

    score_idx = pred_header.index("sa_score")
    smiles_idx = pred_header.index("smiles")

    pred_scores = {}
    valid_count = 0
    for line in pred_lines[1:]:
        parts = line.split("\t")
        if len(parts) <= max(score_idx, smiles_idx):
            continue
        try:
            score = float(parts[score_idx])
            smiles = parts[smiles_idx].strip()
            if smiles:
                pred_scores[smiles] = score
                valid_count += 1
        except ValueError:
            continue

    if valid_count < 100:
        return False, f"Too few valid molecules: {valid_count} (need at least 100)"

    for smiles, score in pred_scores.items():
        if score < 1.0 or score > 10.0:
            return False, f"SA score {score} for '{smiles}' outside valid range [1, 10]"

    gold_header = gold_lines[0].split("\t")
    gold_score_idx = gold_header.index("sa_score")
    gold_smiles_idx = gold_header.index("smiles")

    gold_scores = {}
    for line in gold_lines[1:]:
        parts = line.split("\t")
        if len(parts) <= max(gold_score_idx, gold_smiles_idx):
            continue
        try:
            gold_scores[parts[gold_smiles_idx].strip()] = float(parts[gold_score_idx])
        except ValueError:
            continue

    matched = 0
    total_error = 0.0
    for smiles, pred_score in pred_scores.items():
        if smiles in gold_scores:
            matched += 1
            total_error += abs(pred_score - gold_scores[smiles])

    if matched < 50:
        return False, f"Too few matching molecules with gold: {matched} (need at least 50)"

    mae = total_error / matched
    if mae > 0.5:
        return False, f"Mean absolute error {mae:.4f} exceeds threshold 0.5"

    return True, (
        f"Evaluation passed: {valid_count} valid molecules, "
        f"{matched} matched with gold, MAE={mae:.4f}"
    )


if __name__ == "__main__":
    success, reason = eval()
    print(f"Result: {success}")
    print(f"Reason: {reason}")
    sys.exit(0 if success else 1)
