    # Compare mean of bottom rows (south) vs top rows (north)
    south_mean = np.mean(pred_mean[-10:, :])
    north_mean = np.mean(pred_mean[:10, :])
    # In the gold, south (high lat index = higher lat = north) actually has LOWER temps
    # Wait - g_lat goes from 47 (south) to 56 (north), so index 0 = south, last = north
    # For Germany in summer, south is typically warmer
    south_mean_temp = np.mean(pred_mean[:10, :])   # lat ~47-48 (south)
    north_mean_temp = np.mean(pred_mean[-10:, :])   # lat ~55-56 (north)
    # Just check that there IS a gradient (difference > 0.5 degrees)
    if abs(south_mean_temp - north_mean_temp) < 0.5:
        return (False, "Mean drift field does not show expected north-south temperature gradient")

    # === Step 5: Final result ===
    details = (
        f"All checks passed. "
        f"Temp field RMSE vs gold: {temp_rmse:.4f}, R^2: {temp_r2:.4f}. "
        f"Mean field RMSE vs gold: {mean_rmse:.4f}. "
        f"Variogram params - variance: {variance:.2f}, len_scale: {len_scale:.1f} km, nugget: {nugget:.2f}. "
        f"Temp range: [{np.min(pred_temp):.1f}, {np.max(pred_temp):.1f}]."
    )
