    # Helper function to find a key in nested dict (case-insensitive, underscore-flexible)
    def find_value(d, *possible_keys):
        """Try to find a value using multiple possible key names."""
        if not isinstance(d, dict):
            return None
        for key in possible_keys:
            if key in d:
                return d[key]
        # Try case-insensitive
        for k, v in d.items():
            for key in possible_keys:
                if k.lower() == key.lower() or k.lower().replace('_', '') == key.lower().replace('_', ''):
                    return v
        return None

    def find_section(d, *possible_keys):
        """Find a nested section using multiple possible key names."""
        result = find_value(d, *possible_keys)
        return result if isinstance(result, dict) else None

    # 1. Check that the JSON has some meaningful structure
    if not isinstance(pred, dict):
        return (False, "Output JSON is not a dictionary")

    if len(pred) == 0:
        return (False, "Output JSON is empty")

    # 2. Find statistics section (flexible naming)
    stats = find_section(pred, 
        'statistics', 'dataset_statistics', 'stats', 
        'dataset_stats', 'data_statistics'
    )

    if stats is None:
