import os
import struct


REQUIRED_FILES = [
    "pred_example_features.pdf",
    "hardcoded_14_features.pdf",
    "hardcoded_homo_features.pdf",
]

PRED_DIR = "pred_results"
GOLD_DIR = os.path.join(".", "benchmark", "eval_programs", "gold_results")


def is_valid_pdf(filepath):
    """Check if a file is a valid PDF by examining its header and structure."""
    try:
        with open(filepath, 'rb') as f:
            header = f.read(5)
            if header != b'%PDF-':
                return False, "Missing PDF header"
            # Check for EOF marker
            f.seek(-1024, 2)  # Seek near end
            tail = f.read()
            if b'%%EOF' not in tail and b'startxref' not in tail:
                return False, "Missing PDF EOF marker"
        return True, "Valid PDF"
    except Exception as e:
        return False, str(e)


def count_pdf_pages(filepath):
    """Count pages in a PDF by counting /Page objects (simple heuristic)."""
    try:
        with open(filepath, 'rb') as f:
            content = f.read()
        # Count /Type /Page entries (not /Pages)
        import re
        # Look for page objects
        pages = re.findall(rb'/Type\s*/Page\b', content)
        if len(pages) > 0:
            return len(pages)
        # Fallback: check /Count in /Pages
        counts = re.findall(rb'/Count\s+(\d+)', content)
        if counts:
            return int(counts[-1])
        return 1  # Assume at least 1 page if we can't determine
    except Exception:
        return -1


def eval():
    missing_pred = []

    for fname in REQUIRED_FILES:
        pred_path = os.path.join(PRED_DIR, fname)
        if not os.path.isfile(pred_path):
            missing_pred.append(fname)

    if missing_pred:
        return (False, f"Predicted result files missing: {missing_pred}")

    # Validate each predicted PDF
    for fname in REQUIRED_FILES:
        pred_path = os.path.join(PRED_DIR, fname)

        # Check non-empty
        pred_size = os.path.getsize(pred_path)
        if pred_size == 0:
            return (False, f"Predicted file {fname} is empty (0 bytes)")

        # Minimum reasonable size for a matplotlib PDF with a pie chart
        # A minimal PDF with graphical content should be at least a few KB
        if pred_size < 1000:
            return (False, f"Predicted file {fname} is suspiciously small ({pred_size} bytes)")

        # Check valid PDF format
        valid, reason = is_valid_pdf(pred_path)
        if not valid:
            return (False, f"Predicted file {fname} is not a valid PDF: {reason}")

        # Check page count (should be at least 1)
        num_pages = count_pdf_pages(pred_path)
        if num_pages == 0:
            return (False, f"Predicted file {fname} appears to have no pages")

        # If gold files exist, do additional comparison
        gold_path = os.path.join(GOLD_DIR, fname)
        if os.path.isfile(gold_path):
            gold_size = os.path.getsize(gold_path)
            if gold_size > 0:
                size_ratio = pred_size / gold_size
                # Allow generous range since different matplotlib versions produce different sizes
                if size_ratio < 0.1 or size_ratio > 10.0:
                    return (
                        False,
                        f"{fname}: file size {pred_size} bytes is too different from gold "
                        f"{gold_size} bytes (ratio={size_ratio:.2f})",
                    )

    return (True, "All 3 required PDF files exist, are valid, non-empty PDFs with graphical content")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")"}

