        pred_path = os.path.join(pred_dir, f)
        if not os.path.exists(pred_path):
            return (False, f"Missing required file: {f}")

    # 2. Load pred CSV - handle both labeled and unlabeled formats
    csv_path = os.path.join(pred_dir, "pred_eeg_graph_visualization.csv")
    try:
        # Try reading with pandas first (handles labeled CSVs)
        pred_df = pd.read_csv(csv_path, index_col=0)
        pred_csv = pred_df.values.astype(float)
    except Exception:
        try:
            # Fallback: try plain numeric
            pred_csv = np.loadtxt(csv_path, delimiter=",")
        except Exception as e:
            return (False, f"Could not load CSV file: {e}")

    # Check shape - should be 19x19 (standard 10-20 system has 19 electrodes)
    if pred_csv.shape != (19, 19):
        return (False, f"CSV matrix shape is {pred_csv.shape}, expected (19, 19)")

    # Check adjacency matrix properties
    # Symmetry
    if not np.allclose(pred_csv, pred_csv.T, atol=1e-5):
        return (False, "Adjacency matrix is not symmetric")

    # Zero diagonal
    if not np.allclose(np.diag(pred_csv), 0, atol=1e-5):
        return (False, "Adjacency matrix diagonal is not zero")

    # Check values are non-negative
    if np.any(pred_csv < -1e-6):
        return (False, "Adjacency matrix contains negative values")

    # Check that matrix has some non-zero entries (it's a connectivity graph)
    nonzero_count = np.count_nonzero(pred_csv > 1e-6)
    if nonzero_count == 0:
        return (False, "Adjacency matrix has no non-zero entries")

    # Load original data for comparison
    try:
        file_path = 'benchmark/datasets/eeg-gnn-ssl/data/electrode_graph/adj_mx_3d.pkl'
        with open(file_path, 'rb') as f:
            data = pickle.load(f)
