    # Should have at least some electrode names mentioned
    if len(found_electrodes) < 5:
        return (False, f"Text report mentions too few electrode names. Found: {found_electrodes}")

    # 4. Validate PNG files are valid images and not empty
    for png_file in ["pred_eeg_graph_visualization.png", "pred_eeg_graph_visualization_detailed.png"]:
