import os
import numpy as np


def find_column(df, *keywords):
    """Find a column in df that contains any of the keywords (case-insensitive)."""
    cols = df.columns.tolist()
    for keyword in keywords:
        for col in cols:
            if keyword.lower() in col.lower():
                return col
    return None


def eval():
