    try:
        student_df = pd.read_csv(os.path.join(data_dir, 'student.csv'))
        family_df = pd.read_csv(os.path.join(data_dir, 'family.csv'))
        school_df = pd.read_csv(os.path.join(data_dir, 'school.csv'))
        term_eng_df = pd.read_csv(os.path.join(data_dir, 'term-eng.csv'))
    except Exception as e:
        return (False, f"Error loading source data: {e}")

