    if inter_exer_col is None:
        return (False, "Interaction file missing exercise/question ID column")
    if inter_score_col is None:
        return (False, "Interaction file missing score/label column")
    if inter_time_col is None:
        return (False, "Interaction file missing timestamp/time column")

    # Validate score normalization (should be in [0, 1])
    scores = pd.to_numeric(pred_inter[inter_score_col], errors='coerce').dropna()
    if len(scores) == 0:
        return (False, "Interaction file score column has no valid numeric values")
    if scores.min() < -0.01 or scores.max() > 1.01:
        return (False, f"Scores not normalized to [0,1]: min={scores.min():.4f}, max={scores.max():.4f}")

    # Validate row count for interactions
    # Expected: rows from term-eng.csv (possibly filtered)
    expected_inter_rows = len(term_eng_df)
    actual_inter_rows = len(pred_inter)
