    if abs(actual_inter_rows - expected_inter_rows) > max(10, expected_inter_rows * 0.1):
        return (False, f"Interaction file row count unexpected: got {actual_inter_rows}, expected ~{expected_inter_rows}")

    # Validate that scores are correctly normalized
    # Check a sample: score / full_score should match pred score
