def parse_fasta(filepath):
    """Parse a FASTA file into a list of (header, sequence) tuples."""
    sequences = []
    current_header = None
    current_seq_parts = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.rstrip()
            if line.startswith(">"):
