    # Check that critical columns exist in raw data
    pos_col = find_col(pred_raw, ["pos", "position", "bp", "start"])
    chrom_col = find_col(pred_raw, ["chrom", "chromosome", "chr"])
    pval_col = find_col(pred_raw, ["pval", "p_value", "pvalue", "p-value", "pvalue"])

    if chrom_col is None:
        return (False, "Raw data missing chromosome column (tried: chrom, chromosome, chr)")
    if pos_col is None:
        return (False, "Raw data missing position column (tried: pos, position, bp)")
    if pval_col is None:
        return (False, "Raw data missing p-value column (tried: pval, p_value, pvalue, p-value)")

    # 3. Validate genomic region - all SNPs should be on chr9, positions 4M-6M
    chroms = pred_raw[chrom_col].astype(str).str.replace("chr", "", regex=False).str.strip()
    if not all(chroms == "9"):
