    if max_seq_len == 0:
        return (False, "All sample lines have empty sequences")

    return (True, f"All checks passed: JSON format correct, metadata complete, {len(sample_lines)} sample lines validated with correct tab-separated format (user_id, problem_seq, correctness_seq)")


