#!/usr/bin/env python3
"""Preprocess PyKT educational interaction datasets into standard tab-separated sequences.

The script:
  1. Automatically detects raw interaction CSV datasets under
     ``benchmark/datasets/pykt-toolkit/data``.  A dataset is a raw CSV with
     student/problem/correctness columns, or a sub-directory containing such a
     CSV (e.g. assist2015/assist2015.csv).
  2. Prioritises the ``assist2015`` dataset if it is present and non-empty.
  3. Groups rows by student, orders interactions chronologically when a
     timestamp column is available, and writes lines of the form:
         <user_id>\t<problem1,problem2,...>\t<correct1,correct2,...>
  4. Writes the standardised TSV to ``pred_results/processed_data.tsv`` and
     metadata/results to ``pred_results/pred_data_proprocess.json``.
"""

from __future__ import annotations

import csv
import json
import re
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

BASE_DIR = Path(__file__).resolve().parent
DATA_DIR = BASE_DIR / "benchmark" / "datasets" / "pykt-toolkit" / "data"
PRED_RESULTS_DIR = BASE_DIR / "pred_results"
OUTPUT_TSV = PRED_RESULTS_DIR / "processed_data.tsv"
OUTPUT_JSON = PRED_RESULTS_DIR / "pred_data_proprocess.json"

PRIORITY_DATASET = "assist2015"

# Column-name aliases for raw interaction CSV files.
USER_COLUMNS = {
    "studentid",
    "student_id",
    "student",
    "userid",
    "user_id",
    "user",
    "uid",
    "anon_student_id",
}
# Primary problem/item identifiers.  Skill columns are deliberately NOT in this
# list because for datasets such as ASSISTments the problem/item id is the
# sequence element used by PyKT.
PROBLEM_COLUMNS = {
    "problemid",
    "problem_id",
    "questionid",
    "question_id",
    "itemid",
    "item_id",
    "item",
    "problem",
    "question",
    "problem_name",
    "question_name",
}
SKILL_COLUMNS = {
    "skillid",
    "skill_id",
    "skill",
    "skill_name",
    "concept",
    "concept_id",
    "kc_id",
}
CORRECT_COLUMNS = {
    "correct",
    "correctness",
    "iscorrect",
    "is_correct",
    "correct_flag",
    "label",
    "response",
}
TIMESTAMP_COLUMNS = {
    "starttime",
    "start_time",
    "timestamp",
    "time",
    "endtime",
    "end_time",
}


def _norm_colname(name: str) -> str:
    """Return a normalised lowercase column name without punctuation/underscores."""
    return re.sub(r"[\s_\-./\\]+", "", name).lower()


def _read_csv_header(path: Path) -> List[str]:
    with path.open("r", newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return []
    return header


def _find_column(header: Sequence[str], aliases: Iterable[str]) -> Optional[str]:
    """Return the first header cell matching one of the aliases (normalised)."""
    alias_set = {_norm_colname(a) for a in aliases}
    for col in header:
        if _norm_colname(col) in alias_set:
            return col
    return None


def _is_raw_interaction_csv(path: Path) -> bool:
    """Heuristic: raw CSV has student, problem and correctness columns."""
    try:
        header = _read_csv_header(path)
    except (OSError, UnicodeDecodeError):
        return False
    if not header:
        return False
    return bool(
        _find_column(header, USER_COLUMNS)
        and _find_column(header, PROBLEM_COLUMNS)
        and _find_column(header, CORRECT_COLUMNS)
    )


def _is_sequence_csv(path: Path) -> bool:
    """Heuristic: already sequence-format CSV (PyKT train_valid_sequences style)."""
    try:
        header = _read_csv_header(path)
    except (OSError, UnicodeDecodeError):
        return False
    norm = {_norm_colname(h) for h in header}
    return {"uid", "questions", "responses"}.issubset(norm) or {
        "fold",
        "uid",
        "questions",
        "responses",
    }.issubset(norm)


def _find_assist2015_candidates(data_dir: Path) -> List[Path]:
    """Return CSV files inside an assist2015 dataset directory, if any."""
    assist_dir = data_dir / PRIORITY_DATASET
    if not assist_dir.is_dir():
        return []
    candidates = sorted([p for p in assist_dir.rglob("*.csv") if p.is_file()])
    # Prefer raw interaction CSVs; otherwise accept any CSV in that directory.
    raw = [p for p in candidates if _is_raw_interaction_csv(p)]
    return raw or candidates


def detect_datasets(data_dir: Path) -> List[Dict[str, object]]:
    """Detect raw CSV datasets, with assist2015 prioritised when present.

    Returns a list of dataset descriptors ordered by priority.
    """
    datasets: List[Dict[str, object]] = []

    # 1) Top priority: a non-empty assist2015 directory/dataset.
    assist_candidates = _find_assist2015_candidates(data_dir)
    for csv_path in assist_candidates:
        if _is_raw_interaction_csv(csv_path):
            dtype = "raw_csv"
        elif _is_sequence_csv(csv_path):
            dtype = "sequence_csv"
        else:
            dtype = "unknown_csv"
        datasets.append(
            {
                "name": PRIORITY_DATASET,
                "input_file": str(csv_path.relative_to(BASE_DIR)),
                "type": dtype,
                "priority": True,
            }
        )

    # 2) Other raw CSV files inside dataset sub-directories (PyKT's usual
    #    layout is data/<dataset>/<dataset>.csv).
    if data_dir.is_dir():
        for subdir in sorted([p for p in data_dir.iterdir() if p.is_dir()]):
            if subdir.name == PRIORITY_DATASET:
                continue  # already handled above
            sub_csvs = sorted([p for p in subdir.rglob("*.csv") if p.is_file()])
            for csv_path in sub_csvs:
                if _is_raw_interaction_csv(csv_path):
                    datasets.append(
                        {
                            "name": subdir.name,
                            "input_file": str(csv_path.relative_to(BASE_DIR)),
                            "type": "raw_csv",
                            "priority": False,
                        }
                    )
                elif _is_sequence_csv(csv_path):
                    datasets.append(
                        {
                            "name": subdir.name,
                            "input_file": str(csv_path.relative_to(BASE_DIR)),
                            "type": "sequence_csv",
                            "priority": False,
                            "note": "Already in sequence format; skipped raw conversion.",
                        }
                    )

    # 3) Raw CSV files directly in the data directory (exclude already
    #    sequence-level files such as train_valid_sequences.csv and data.txt).
    if data_dir.is_dir():
        for csv_path in sorted(data_dir.glob("*.csv")):
            if csv_path in assist_candidates:
                continue
            if _is_raw_interaction_csv(csv_path):
                datasets.append(
                    {
                        "name": csv_path.stem,
                        "input_file": str(csv_path.relative_to(BASE_DIR)),
                        "type": "raw_csv",
                        "priority": False,
                    }
                )
            elif _is_sequence_csv(csv_path):
                # Record for metadata but do not treat as a raw CSV needing conversion.
                datasets.append(
                    {
                        "name": csv_path.stem,
                        "input_file": str(csv_path.relative_to(BASE_DIR)),
                        "type": "sequence_csv",
                        "priority": False,
                        "note": "Already in sequence format; skipped raw conversion.",
                    }
                )

    # 4) If no raw CSV dataset was found, fall back to sequence-format CSVs.
    raw_datasets = [d for d in datasets if d.get("type") == "raw_csv"]
    if not raw_datasets:
        if data_dir.is_dir():
            for csv_path in sorted(data_dir.glob("*.csv")):
                if _is_sequence_csv(csv_path):
                    datasets.append(
                        {
                            "name": csv_path.stem,
                            "input_file": str(csv_path.relative_to(BASE_DIR)),
                            "type": "sequence_csv",
                            "priority": False,
                            "note": "Fallback sequence CSV; will be standardised if columns permit.",
                        }
                    )

    return datasets


def _normalise_correctness(value: object) -> str:
    """Normalise a raw correctness value to '0' or '1'."""
    if value is None:
        return "0"
    s = str(value).strip().lower()
    if s in {"1", "1.0", "true", "t", "yes", "y", "correct"}:
        return "1"
    if s in {"0", "0.0", "false", "f", "no", "n", "incorrect", "nan", ""}:
        return "0"
