import numpy as np
from ase.io.trajectory import Trajectory


def eval():
    gold_path = "./gold_results/pred_coltraj.traj"
    pred_path = "pred_results/pred_coltraj.traj"

    # Check predicted file exists and is readable
    try:
        pred_traj = Trajectory(pred_path)
    except Exception as e:
        return (False, f"Cannot open predicted trajectory: {e}")

    # Load gold trajectory
    try:
        gold_traj = Trajectory(gold_path)
    except Exception as e:
        return (False, f"Cannot open gold trajectory: {e}")

    # Check frame count matches
    n_pred = len(pred_traj)
    n_gold = len(gold_traj)
    if n_pred != n_gold:
        return (False, f"Frame count mismatch: predicted {n_pred}, expected {n_gold}")

    # Compare each frame
    tol = 1e-10
    for i in range(n_gold):
        gold_atoms = gold_traj[i]
        pred_atoms = pred_traj[i]

        # Check number of atoms
        if len(pred_atoms) != len(gold_atoms):
            return (False, f"Frame {i}: atom count mismatch ({len(pred_atoms)} vs {len(gold_atoms)})")

        # Check chemical symbols
        if pred_atoms.get_chemical_symbols() != gold_atoms.get_chemical_symbols():
            return (False, f"Frame {i}: chemical symbols mismatch")

        # Check positions
        pos_diff = np.max(np.abs(pred_atoms.get_positions() - gold_atoms.get_positions()))
        if pos_diff > tol:
            return (False, f"Frame {i}: positions differ by {pos_diff:.2e} (tolerance {tol})")

        # Check cell parameters
        cell_diff = np.max(np.abs(np.array(pred_atoms.get_cell()) - np.array(gold_atoms.get_cell())))
        if cell_diff > tol:
            return (False, f"Frame {i}: cell parameters differ by {cell_diff:.2e} (tolerance {tol})")

    return (True, f"All {n_gold} frames match exactly within tolerance")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")---
