import os
import pandas as pd
import numpy as np
from PIL import Image


def compute_expected_metrics(file_path):
    """Compute expected metrics directly from the source data."""
    df = pd.read_csv(file_path)
    total_df = df[df['Ticker'] == 'TOTAL'].copy()

    dates = total_df['Date'].tolist()
    equity = [float(e) for e in total_df['Total Equity'].tolist()]

    if len(equity) < 2:
        return None

    # Method 1: Compute largest run-up tracking running minimum
    min_equity = equity[0]
    min_date = dates[0]
    max_gain_method1 = 0
    start_run_date_m1 = dates[0]
    end_run_date_m1 = dates[0]
    best_min_equity_m1 = equity[0]

    for i in range(1, len(dates)):
        current_date = dates[i]
        current_equity = equity[i]
        if current_equity < min_equity:
            min_equity = current_equity
            min_date = current_date
        current_gain = current_equity - min_equity
        if current_gain > max_gain_method1:
            max_gain_method1 = current_gain
            start_run_date_m1 = min_date
            end_run_date_m1 = current_date
            best_min_equity_m1 = min_equity

    gain_pct_m1 = (max_gain_method1 / best_min_equity_m1) * 100 if best_min_equity_m1 != 0 else 0

    # Method 2: From each point, find max future value (alternative valid interpretation)
    max_gain_pct_m2 = 0
    start_run_date_m2 = dates[0]
    end_run_date_m2 = dates[0]

    equity_arr = np.array(equity)
    for i in range(len(equity)):
        future_max = equity_arr[i:].max()
        gain_pct = (future_max - equity_arr[i]) / equity_arr[i] * 100 if equity_arr[i] != 0 else 0
        if gain_pct > max_gain_pct_m2:
            max_gain_pct_m2 = gain_pct
            start_run_date_m2 = dates[i]
            peak_idx = i + np.argmax(equity_arr[i:])
            end_run_date_m2 = dates[peak_idx]

    # Compute maximum drawdown
    max_so_far = equity[0]
    max_drawdown = 0
    drawdown_date = dates[0]
    drawdown_equity = equity[0]

    for i in range(1, len(dates)):
        current_date = dates[i]
        current_equity = equity[i]
        if current_equity > max_so_far:
            max_so_far = current_equity
        current_drawdown = (current_equity - max_so_far) / max_so_far * 100 if max_so_far != 0 else 0
        if current_drawdown < max_drawdown:
            max_drawdown = current_drawdown
            drawdown_date = current_date
            drawdown_equity = current_equity

    # Final profit/loss
    final_profit_loss = ((equity[-1] - equity[0]) / equity[0]) * 100 if equity[0] != 0 else 0

    return {
        # Method 1 results
        'start_run_date_m1': start_run_date_m1,
        'end_run_date_m1': end_run_date_m1,
        'gain_percentage_m1': gain_pct_m1,
        # Method 2 results
        'start_run_date_m2': start_run_date_m2,
        'end_run_date_m2': end_run_date_m2,
        'gain_percentage_m2': max_gain_pct_m2,
        # Drawdown (same for both)
        'drawdown_date': drawdown_date,
        'drawdown_equity': drawdown_equity,
        'max_drawdown_pct': abs(max_drawdown),
        'final_profit_loss': final_profit_loss
    }


def find_column_flexible(df, candidates):
    """Find a column in df from a list of candidate names (case-insensitive, space/underscore agnostic)."""
    def normalize(s):
        return s.lower().replace(' ', '').replace('_', '').replace('-', '')

    df_cols_normalized = {normalize(c): c for c in df.columns}
    for candidate in candidates:
        normalized = normalize(candidate)
        if normalized in df_cols_normalized:
            return df_cols_normalized[normalized]
    return None


