    if re.search(r'(total\s*classes|classes\s*found|num.*class)', pred_lower):
        data_loaded = True
    if re.search(r'\d+\s*(classes|samples|windows|files)', pred_lower):
        data_loaded = True
    if re.search(r'(loaded|discovered|found|processed).*\d+', pred_lower):
        data_loaded = True
    # Check for class names that look like CWRU fault types
    if re.search(r'(normal|inner|outer|ball|fault|bearing)', pred_lower):
        data_loaded = True
    if not data_loaded:
        return (False, "Output does not show evidence of data loading or class discovery.")

    # Step 2: Verify train/test split is documented
    has_train = bool(re.search(r'train', pred_lower))
    has_test = bool(re.search(r'test', pred_lower))
    if not (has_train and has_test):
