    if train_match and test_match:
        n_train = int(train_match.group(1))
        n_test = int(test_match.group(1))
        if n_train < 1:
            return (False, f"Only {n_train} train classes found, expected at least 1.")
        if n_test < 1:
            return (False, f"Only {n_test} test classes found, expected at least 1.")
        # Train should generally be larger than test
        total = n_train + n_test
        if total < 2:
            return (False, f"Total classes ({total}) seems too low.")

    # Step 3: Verify sample length is 1024
    if '1024' not in pred_text:
        return (False, "Output does not contain expected sample length of 1024.")

