        audio_path = 'benchmark/datasets/shennong/test/data/test.wav'
        sample_rate, audio_data = wavfile.read(audio_path)
        if audio_data.ndim > 1:
            audio_data = audio_data[:, 0]
        audio_duration = len(audio_data) / sample_rate
        # Expected number of frames with 10ms shift
        expected_frames = int(audio_duration / 0.01)
    except Exception as e:
        return (False, f"Could not load reference audio: {e}")

    # Load predicted CSV - handle with or without header
    pred_rows = []
    try:
        with open(pred_csv, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                try:
                    values = [float(x) for x in line.split(',')]
                    pred_rows.append(values)
                except ValueError:
                    # Skip header lines that can't be parsed as floats
                    continue
    except Exception as e:
        return (False, f"Failed to read predicted CSV: {e}")

    if len(pred_rows) == 0:
        return (False, "Predicted CSV has no parseable data rows")

    pred_arr = np.array(pred_rows)

    # Step 2: Determine orientation and validate dimensions
    # The CSV should have frame timestamps in first column followed by frequency bins
    # Shape should be (n_frames, 1 + n_freq_bins)
    # OR it could be transposed (n_freq_bins, 1 + n_frames) - less likely given task description

    n_rows, n_cols = pred_arr.shape

    if n_rows < 2 or n_cols < 2:
        return (False, f"CSV dimensions too small: {n_rows} rows x {n_cols} cols")

    # Check if first column could be timestamps (monotonically increasing, small values)
    first_col = pred_arr[:, 0]
    first_row = pred_arr[0, :]

    # Determine if rows = frames or rows = frequency bins
    # Timestamps should be monotonically increasing and in range [0, duration]
    first_col_monotonic = np.all(np.diff(first_col) > 0)
    first_col_in_range = first_col[0] >= 0 and first_col[-1] <= audio_duration * 2

    first_row_monotonic = np.all(np.diff(first_row) > 0)
    first_row_in_range = first_row[0] >= 0 and first_row[-1] <= audio_duration * 2

    if first_col_monotonic and first_col_in_range:
        # Standard orientation: rows=frames, cols=freq_bins
        timestamps = pred_arr[:, 0]
        spec_values = pred_arr[:, 1:]
        n_frames = n_rows
        n_freq_bins = n_cols - 1
        orientation = "standard (rows=frames)"
    elif first_row_monotonic and first_row_in_range:
        # Transposed: rows=freq_bins, first_row=timestamps
        # This would be unusual given task description, but handle it
        timestamps = pred_arr[0, 1:]  # skip first element if it's a label
        spec_values = pred_arr[1:, 1:]
        n_frames = n_cols - 1
        n_freq_bins = n_rows - 1
        orientation = "transposed (rows=freq_bins)"
    else:
        # Try standard orientation anyway
        timestamps = pred_arr[:, 0]
        spec_values = pred_arr[:, 1:]
        n_frames = n_rows
        n_freq_bins = n_cols - 1
        orientation = "assumed standard"

    # Step 3: Validate frame count
    # Allow generous tolerance for boundary handling differences
    frame_tolerance = max(20, int(expected_frames * 0.1))  # 10% tolerance or at least 20 frames
    if abs(n_frames - expected_frames) > frame_tolerance:
        return (False, f"Frame count mismatch: predicted {n_frames}, expected ~{expected_frames} (±{frame_tolerance}). Orientation: {orientation}")

    # Step 4: Validate frequency bins
