            continue

    if integrity_failures > 0:
        return (False, f"Data integrity check failed: {integrity_failures}/{integrity_checks} sampled entries differ from gold")

    # Step 9: Validate summary statistics match gold
    gold_total = gold_summary.get("total_samples")
    pred_total = pred_summary.get("total_samples")
    if gold_total != pred_total:
