    ]

    pred_path = None
    for path in possible_paths:
        if os.path.exists(path):
            pred_path = path
            break

    # Also search for any PNG files in pred_results directory
    if pred_path is None:
        png_files = glob.glob("pred_results/*.png") + glob.glob("pred_results/*.PNG")
        if png_files:
            pred_path = png_files[0]

    if pred_path is None:
        # Check if pred_results directory exists
        if not os.path.exists("pred_results"):
            return (False, "pred_results directory does not exist. The solution must create this directory and save the plot there.")
        return (False, "Predicted output file pred_results/pred_fig_process.png does not exist.")

    # 2. Check file size (must be >5KB to contain actual plot content)
    file_size = os.path.getsize(pred_path)
    if file_size < 5 * 1024:
        return (False, f"Predicted image is too small ({file_size} bytes), likely not a valid plot.")

    # 3. Validate it's a real image file
    try:
        from PIL import Image
        img = Image.open(pred_path)
        img.verify()
    except ImportError:
        # If PIL not available, just check it's a non-empty file
        if file_size < 1024:
            return (False, f"File too small to be a valid image: {file_size} bytes")
        return (True, f"Plot file exists and has reasonable size ({file_size} bytes). PIL not available for deeper validation.")
    except Exception as e:
        return (False, f"Predicted file is not a valid image: {e}")

    # Reopen after verify (verify closes the file)
    img = Image.open(pred_path)
    width, height = img.size

    # Basic sanity: image should have reasonable dimensions for a plot
    if width < 200 or height < 200:
        return (False, f"Image dimensions too small ({width}x{height}), likely not a proper plot.")

    # 4. Verify the data pipeline by checking source data
    data_path = "benchmark/datasets/DHDRL/RatevsTimeslot/rate500000R100AP6UE3QoS.json"

