def _extract_niqe_score(filepath):
    """Extract the NIQE score from a result file."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
    except Exception:
        return None

    # Try "NIQE Score: <value>" or "NIQE score: <value>" pattern
    match = re.search(r'NIQE\s*[Ss]core\s*[:=]\s*([+-]?\d+\.?\d*(?:[eE][+-]?\d+)?)', content)
    if match:
        try:
            return float(match.group(1))
        except ValueError:
            pass

    # Try "niqe" followed by a number
    match = re.search(r'niqe\s*[:=]\s*([+-]?\d+\.?\d*(?:[eE][+-]?\d+)?)', content, re.IGNORECASE)
    if match:
        try:
            return float(match.group(1))
        except ValueError:
            pass

    # Try "score" followed by a number
    match = re.search(r'[Ss]core\s*[:=]\s*([+-]?\d+\.?\d*(?:[eE][+-]?\d+)?)', content)
    if match:
        try:
            return float(match.group(1))
        except ValueError:
            pass

    # Fallback: first float in the file
    match = re.search(r'([+-]?\d+\.\d+(?:[eE][+-]?\d+)?)', content)
    if match:
        try:
            return float(match.group(1))
        except ValueError:
            pass

    return None


