def _is_valid_float(s):
    try:
        v = float(s)
        return not (v != v or abs(v) == float('inf'))
    except:
        return False


def _parse_sections_flexible(text, prob_names):
    """More flexible section parser."""
    sections = {}
    lines = text.split('\n')
    current_problem = None
    current_lines = []

    for line in lines:
        matched = None
        for prob in prob_names:
            if prob in line:
                idx = line.find(prob)
                after = line[idx + len(prob):idx + len(prob) + 1]
                if not after.isdigit():
                    matched = prob
                    break

        if matched and matched != current_problem:
            if current_problem:
                sections[current_problem] = '\n'.join(current_lines)
            current_problem = matched
            current_lines = [line]
        elif current_problem:
            current_lines.append(line)

    if current_problem:
        sections[current_problem] = '\n'.join(current_lines)

    return sections


