    # 5. Check training completion status
    completion_val = pred[completion_key]
    if not completion_val:
        return (False, f"Training did not complete successfully: {completion_key}={completion_val}")

    # 6. Check total_epochs equals 1
    if pred["total_epochs"] != 1:
        return (False, f"Expected total_epochs=1, got {pred['total_epochs']}")

    # 7. Validate numeric metrics
    for field in ["final_reward", "final_loss"]:
        val = pred[field]
        if not isinstance(val, (int, float)):
            return (False, f"{field} is not numeric: {val}")
        if math.isnan(val) or math.isinf(val):
            return (False, f"{field} is not finite: {val}")

