import json
import os
import math
import numpy as np
import pickle


def eval():
    pred_path = "pred_results/pred_stacking_dataset.json"

    # Step 1: Check file existence and JSON validity
    if not os.path.exists(pred_path):
        return (False, "Predicted output file not found: pred_results/pred_stacking_dataset.json")

    try:
        with open(pred_path, "r") as f:
            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as e:
        return (False, f"Failed to parse predicted JSON: {e}")

    if not pred:
        return (False, "Predicted JSON is empty")

    # Check for error indicators
    if "error" in pred or ("status" in pred and pred.get("status") == "failed"):
        return (False, f"Predicted output indicates failure: {pred.get('error', 'unknown error')}")

    # Step 2: Validate required structure - find observation and action stats
    def find_obs_stats(d):
        if "observation_stats" in d:
            return d["observation_stats"]
        if "statistics" in d and isinstance(d["statistics"], dict):
            s = d["statistics"]
            if "observations" in s:
                return s["observations"]
            if "observation" in s:
                return s["observation"]
        if "obs_stats" in d:
            return d["obs_stats"]
        return None

    def find_act_stats(d):
        if "action_stats" in d:
            return d["action_stats"]
        if "statistics" in d and isinstance(d["statistics"], dict):
            s = d["statistics"]
            if "actions" in s:
                return s["actions"]
            if "action" in s:
                return s["action"]
        if "act_stats" in d:
            return d["act_stats"]
        return None

    pred_obs_stats = find_obs_stats(pred)
    pred_act_stats = find_act_stats(pred)

    if pred_obs_stats is None:
        return (False, "Missing observation statistics in predicted output. Expected 'observation_stats' or 'statistics.observations'")
    if pred_act_stats is None:
        return (False, "Missing action statistics in predicted output. Expected 'action_stats' or 'statistics.actions'")

    # Check required stat keys
    required_stat_keys = ["mean", "std", "min", "max"]
    for key in required_stat_keys:
        if key not in pred_obs_stats:
            return (False, f"Missing '{key}' in observation statistics")
        if key not in pred_act_stats:
            return (False, f"Missing '{key}' in action statistics")

    # Step 3: Check dimensional correctness
    pred_obs_dim = len(pred_obs_stats["mean"])
    pred_act_dim = len(pred_act_stats["mean"])

    if pred_obs_dim == 0:
        return (False, "Observation dimension is 0")
    if pred_act_dim == 0:
