    """Find all TSV files recursively under base_dir."""
    tsv_files = {}
    for root, dirs, files in os.walk(base_dir):
        for f in files:
            if f.endswith(".tsv"):
                full_path = os.path.join(root, f)
                rel = os.path.relpath(full_path, base_dir)
                tsv_files[rel] = full_path
    return tsv_files


def _load_tsv(path):
    """Load a TSV file, returning (header_list, list_of_row_lists) or None on error."""
