def find_unemployment_values(pred):
    """Try to extract unemployment rate values from various possible structures."""

    # Structure 1: Gold format - series list with raw values
    if "series" in pred and isinstance(pred["series"], list) and len(pred["series"]) > 0:
        series_item = pred["series"][0]
        if "raw" in series_item:
            values = series_item["raw"]
            if "time" in pred and isinstance(pred["time"], dict) and "raw" in pred["time"]:
                years = pred["time"]["raw"]
                return years, values

    # Structure 2: data as a list of dicts with time and unemployment_rate keys
    if "data" in pred and isinstance(pred["data"], list) and len(pred["data"]) > 0:
        data_list = pred["data"]
        # Check if items have time and unemployment_rate (or similar) keys
        if isinstance(data_list[0], dict):
            # Try to find time key
            time_key = None
            for k in ["time", "year", "date", "period"]:
                if k in data_list[0]:
                    time_key = k
                    break

            # Try to find value key
            value_key = None
            for k in ["unemployment_rate", "rate", "value", "unemployment", "percentage"]:
                if k in data_list[0]:
                    value_key = k
                    break

            if time_key and value_key:
                years = [item[time_key] for item in data_list]
                values = [item[value_key] for item in data_list]
                return years, values

            # If only two keys, assume first is time, second is value
            if len(data_list[0]) == 2:
                keys = list(data_list[0].keys())
                years = [item[keys[0]] for item in data_list]
                values = [item[keys[1]] for item in data_list]
                return years, values

        # Data as list of lists or tuples
        elif isinstance(data_list[0], (list, tuple)) and len(data_list[0]) >= 2:
            years = [item[0] for item in data_list]
            values = [item[1] for item in data_list]
            return years, values

    # Structure 3: Direct unemployment_rate dict {year: rate}
    if "unemployment_rate" in pred and isinstance(pred["unemployment_rate"], dict):
        rate_dict = pred["unemployment_rate"]
        years = sorted(rate_dict.keys(), key=lambda x: int(x) if str(x).isdigit() else x)
        values = [rate_dict[y] for y in years]
        int_years = []
        for y in years:
            try:
                int_years.append(int(y))
            except (ValueError, TypeError):
                int_years.append(y)
        return int_years, values

    # Structure 4: time_index list + unemployment_rate dict
    if "time_index" in pred and "unemployment_rate" in pred:
        years = pred["time_index"]
        rate_dict = pred["unemployment_rate"]
        values = [rate_dict.get(str(y), rate_dict.get(y, None)) for y in years]
        return years, values

    # Structure 5: values/data as a list with separate time index
    for key in ["values", "rates"]:
        if key in pred and isinstance(pred[key], list):
            values = pred[key]
            for time_key in ["time_index", "years", "index", "time"]:
                if time_key in pred:
                    return pred[time_key], values

    # Structure 6: nested under a named series key
    for outer_key in pred:
        if isinstance(pred[outer_key], dict):
            inner = pred[outer_key]
            years, values = find_unemployment_values(inner)
            if years is not None:
                return years, values

    # Structure 7: series as list of dicts with name/values
    if "series" in pred and isinstance(pred["series"], list):
        for series_item in pred["series"]:
            if isinstance(series_item, dict) and "values" in series_item:
                values = series_item["values"]
                if "time" in pred:
