    gold_resized = np.array(PILImage.open(gold_path).convert("RGB").resize(common_size, PILImage.LANCZOS)).astype(float)

    # Compute normalized mean absolute error
    mae = np.mean(np.abs(pred_resized - gold_resized)) / 255.0

