            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as e:
        return (False, f"Failed to parse predicted JSON: {e}")

    errors = []

    # Helper function to search for a value in nested dict
    def find_value(d, keys, default=None):
        """Search for a key in a nested dict, trying multiple possible key names."""
        if not isinstance(d, dict):
            return default
        for key in keys:
            if key in d:
                val = d[key]
                if isinstance(val, dict):
                    continue
                return val
        # Search recursively
        for v in d.values():
            if isinstance(v, dict):
                result = find_value(v, keys, None)
                if result is not None:
                    return result
        return default

    def find_nested(d, keys, default=None):
        """Search for any of the given keys at any nesting level."""
        if not isinstance(d, dict):
            return default
        for key in keys:
            if key in d:
                return d[key]
        for v in d.values():
            if isinstance(v, dict):
                result = find_nested(v, keys, None)
                if result is not None:
                    return result
        return default

