        if coverage < 95:
            return (False, f"Only {coverage:.1f}% of vireo experiment_ids present in prediction. Missing: {list(missing_ids)[:5]}")

    # Step 6: Check row count matches vireo source (or close to it)
    if len(pred1) < len(vireo_df) * 0.95:
        return (False, f"Row count too low: predicted {len(pred1)} vs vireo source {len(vireo_df)}")

    # Step 7: Check no duplicate experiment_ids
    if pred1.index.duplicated().any():
        return (False, "Duplicate experiment_ids found in pred_enhance_vireo_with_metadata.tsv")

    # Step 8: Check that metadata columns from extra_metadata are included
    # The metadata file should have contributed at least some columns to the merged result
    metadata_cols = [c for c in metadata_df.columns if c != 'experiment_id']
    if len(metadata_cols) == 0:
        return (False, "Metadata file has no columns besides experiment_id")

    # Check that at least some metadata columns are present in predictions
    pred_cols = set(pred1.columns)
    matched_meta_cols = [c for c in metadata_cols if c in pred_cols]
    if len(matched_meta_cols) == 0:
        return (False, f"No metadata columns from extra_metadata_donors.tsv found in predictions. Expected some of: {metadata_cols[:5]}")

    # Step 9: Verify metadata values are correctly merged for matching experiment_ids
    # Check a sample of experiment_ids that appear in both vireo and metadata
    if 'experiment_id' in metadata_df.columns:
        common_ids = vireo_ids.intersection(set(metadata_df['experiment_id'].dropna()))
        common_ids_in_pred = common_ids.intersection(pred_ids)

        mismatches = 0
        total_checks = 0
        for exp_id in list(common_ids_in_pred)[:50]:  # Check up to 50 IDs
            meta_row = metadata_df[metadata_df['experiment_id'] == exp_id]
            if meta_row.empty:
                continue
            for col in matched_meta_cols:
                if col not in pred1.columns:
                    continue
                gold_val = meta_row[col].values[0]
                pred_val = pred1.loc[exp_id, col] if exp_id in pred1.index else None

                # Normalize NA-like values
                gold_is_na = pd.isna(gold_val) or str(gold_val).strip().lower() in {"", "nan", "na", "none", "null"}
                pred_is_na = pd.isna(pred_val) or str(pred_val).strip().lower() in {"", "nan", "na", "none", "null"}

                total_checks += 1
                if gold_is_na and pred_is_na:
                    continue
                if gold_is_na != pred_is_na:
                    mismatches += 1
                    continue
                # Compare values
                try:
                    if float(gold_val) != float(pred_val):
                        mismatches += 1
                except (ValueError, TypeError):
                    if str(gold_val).strip() != str(pred_val).strip():
                        mismatches += 1

        if total_checks > 0:
            accuracy = (total_checks - mismatches) / total_checks * 100
            if accuracy < 85:
                return (False, f"Metadata accuracy is {accuracy:.1f}% ({mismatches}/{total_checks} mismatches), below 85% threshold")

    # Step 10: Check vireo n_cells values are preserved correctly
    vireo_ncells_cols = [c for c in vireo_df.columns if c != 'experiment_id']
    for col in vireo_ncells_cols:
        if col not in pred1.columns:
            return (False, f"Vireo column '{col}' not found in predictions")

    # Verify n_cells values match source for a sample
    if 'n_cells' in vireo_df.columns and 'n_cells' in pred1.columns:
        sample_vireo = vireo_df.set_index('experiment_id')
        common = set(sample_vireo.index).intersection(pred_ids)
        ncell_mismatches = 0
        for exp_id in list(common)[:50]:
            gold_ncells = sample_vireo.loc[exp_id, 'n_cells']
            pred_ncells = pred1.loc[exp_id, 'n_cells']
            if pd.notna(gold_ncells) and pd.notna(pred_ncells):
                try:
                    if float(gold_ncells) != float(pred_ncells):
                        ncell_mismatches += 1
                except (ValueError, TypeError):
                    if str(gold_ncells) != str(pred_ncells):
                        ncell_mismatches += 1
        if ncell_mismatches > 0:
            return (False, f"n_cells values don't match source for {ncell_mismatches} experiment_ids")

    # Step 11: Check ground truth assignment files were processed if they exist
    gt_files = glob.glob('GT_replace_*_assignments.tsv')
    if gt_files:
        # If GT files exist, check if any GT-derived columns are present
        # This is optional - the solution may or may not add GT columns
        pass

    # Step 12: Verify both output files are consistent (same content)
    if set(pred1.columns) != set(pred2.columns):
        return (False, f"The two output files have different columns: {set(pred1.columns).symmetric_difference(set(pred2.columns))}")
    if len(pred1) != len(pred2):
        return (False, f"The two output files have different row counts: {len(pred1)} vs {len(pred2)}")

    # Check that indices are the same
    if set(pred1.index) != set(pred2.index):
        return (False, "The two output files have different experiment_ids")

    accuracy_str = f"{accuracy:.1f}% metadata accuracy" if total_checks > 0 else "N/A metadata accuracy"
    return (True, f"All checks passed: {len(pred1)} rows, {len(pred1.columns)} columns, {len(matched_meta_cols)} metadata columns merged, {accuracy_str}")


