def canonicalize_smiles(smiles):
    """Try to canonicalize SMILES using RDKit if available."""
    try:
        from rdkit import Chem
        mol = Chem.MolFromSmiles(smiles)
        if mol:
            return Chem.MolToSmiles(mol)
    except Exception:
        pass
    return smiles.strip()


def get_molecule_name_from_smiles(smiles):
    """Map canonical SMILES to molecule names for flexible matching."""
    name_map = {
        'CCO': 'ethanol',
        'c1ccccc1': 'benzene',
        'CC(=O)O': 'acetic acid',
        'c1ccc2ccccc2c1': 'naphthalene',
        'CC(C)(C)c1ccc(O)cc1': 'BHT',
        'Cn1cnc2c1c(=O)n(C)c(=O)n2C': 'caffeine',
        'CC(Cc1ccc(cc1)C(C(=O)O)C)C': 'ibuprofen',
        'CC(Cc1ccc(cc1)C(C)C(=O)O)': 'ibuprofen',
        'O=C(O)c1ccccc1': 'benzoic acid',
    }
    return name_map.get(smiles, smiles)


