    with open(pred_csv, "r") as f:
        reader = csv.DictReader(f)
        pred_headers = reader.fieldnames
        if pred_headers is None:
            return False, "Predicted CSV has no headers"

        pred_header_lower = [h.strip().lower().replace(" ", "").replace("_", "") for h in pred_headers]

        def find_col(concept, headers_lower, headers_orig):
            for i, h in enumerate(headers_lower):
                if concept in h or h in concept:
                    return headers_orig[i]
            return None

        required_concepts = ["smiles", "logp", "sascore", "ringpenalty", "jscorereward"]
        col_map = {}
        for concept in required_concepts:
            col = find_col(concept, pred_header_lower, pred_headers)
            if col is None:
                return False, f"Missing column matching '{concept}' in predicted CSV. Headers: {pred_headers}"
            col_map[concept] = col

        pred_rows = []
        for row in reader:
            pred_rows.append(row)

    # Step 3: Check we have at least some molecules (at least 4 of the 8)
    if len(pred_rows) < 4:
