    # Step 4: Check that values are numeric and in reasonable ranges
    errors = []
    valid_count = 0

    for row in pred_rows:
        smiles = row[col_map["smiles"]].strip() if col_map["smiles"] in row else ""

        row_valid = True
        for concept in ["logp", "sascore", "ringpenalty", "jscorereward"]:
            try:
                val = float(row[col_map[concept]])
                if not math.isfinite(val):
                    errors.append(f"SMILES={smiles}: {concept}={val} is not finite")
                    row_valid = False
                    continue

                # Check reasonable ranges
                if concept == "logp" and not (-10 <= val <= 20):
                    errors.append(f"SMILES={smiles}: LogP={val} out of reasonable range [-10, 20]")
                    row_valid = False
                elif concept == "sascore" and not (0 <= val <= 15):
                    errors.append(f"SMILES={smiles}: SA Score={val} out of range [0, 15]")
                    row_valid = False
                elif concept == "ringpenalty" and not (-20 <= val <= 30):
