        try:
            jscore_vals.append(float(row[col_map["jscorereward"]]))
            logp_vals.append(float(row[col_map["logp"]]))
        except (ValueError, KeyError):
            pass

    if len(jscore_vals) >= 2:
        jscore_std = (max(jscore_vals) - min(jscore_vals))
        if jscore_std < 1e-9 and len(jscore_vals) > 1:
            return False, f"All Jscore values are identical ({jscore_vals[0]}), which suggests no variation"

    # Step 6: Check baselines file has content and numeric values
    with open(pred_baselines, "r") as f:
