    if len(pred_bl_content.strip()) < 10:
        return False, "Predicted baselines file is too short or empty"

    numbers = re.findall(r"[-+]?\d*\.?\d+", pred_bl_content)
    if len(numbers) < 3:
        return False, f"Baselines file has too few numeric values (found {len(numbers)}, need at least 3)"

    # Step 7: Check that at least some expected molecules are present
    # Try to find ethanol (CCO) or benzene in the SMILES
    smiles_list = [row[col_map["smiles"]].strip() for row in pred_rows if col_map["smiles"] in row]

    # Try to canonicalize SMILES for matching
    canonical_smiles = []
    for smi in smiles_list:
        canonical_smiles.append(canonicalize_smiles(smi))

    # Expected canonical SMILES for the 8 test molecules
    expected_canonical = [
        canonicalize_smiles('CCO'),           # ethanol
        canonicalize_smiles('c1ccccc1'),      # benzene
        canonicalize_smiles('CC(=O)O'),       # acetic acid
        canonicalize_smiles('c1ccc2ccccc2c1'), # naphthalene
        canonicalize_smiles('CC(C)(C)c1ccc(O)cc1'),  # BHT
        canonicalize_smiles('CN1C=NC2=C1C(=O)N(C(=O)N2C)C'),  # caffeine
        canonicalize_smiles('CC(Cc1ccc(cc1)C(C)C(=O)O)C'),  # ibuprofen
        canonicalize_smiles('O=C(O)c1ccccc1'),  # benzoic acid
    ]

    found_count = sum(1 for exp in expected_canonical if exp in canonical_smiles)

    # Also check by simple SMILES string matching (for cases where RDKit isn't available)
    simple_expected = ['CCO', 'c1ccccc1', 'CC(=O)O', 'c1ccc2ccccc2c1', 
                       'CC(C)(C)c1ccc(O)cc1', 'CN1C=NC2=C1C(=O)N(C(=O)N2C)C',
                       'CC(Cc1ccc(cc1)C(C)C(=O)O)C', 'O=C(O)c1ccccc1']
    simple_found = sum(1 for exp in simple_expected if exp in smiles_list)

    best_found = max(found_count, simple_found)

    if best_found < 3:
        # Be lenient - just check we have 8 rows with valid data
        if len(pred_rows) >= 6 and valid_count >= 4:
            return True, f"Found {len(pred_rows)} molecules with {valid_count} valid rows. Molecule matching found {best_found}/8 expected molecules (flexible match accepted)"
        return False, f"Only found {best_found}/8 expected molecules in predictions. Found SMILES: {smiles_list[:5]}"

    # Step 8: Verify that LogP values are physically reasonable for known molecules
    # For ethanol (CCO), LogP should be around -0.3 to 0.5
    # For benzene (c1ccccc1), LogP should be around 1.5 to 2.5
    logp_checks_passed = 0
