        except Exception:
            pass

    # Step 9: Final summary
    summary = (f"Found {len(pred_rows)} molecules, {valid_count} with valid numeric values, "
               f"{best_found}/8 expected molecules matched, "
               f"{len(numbers)} numeric values in baselines file")

