import re


def parse_output(text):
    """Parse the output file with flexible format handling."""
    result = {"files": []}

    # Split by file entries
    blocks = re.split(r'\n(?=File(?:\s+\d+)?:\s*\S)', text)
    if not blocks:
        blocks = [text]

    for block in blocks:
        block = block.strip()
        if not block:
            continue

        # Check if this block starts with a File entry
        path_match = re.match(r'File(?:\s+\d+)?:\s*(.+?)(?:\s*-\s*|\n|$)', block)
        if not path_match:
            continue

        record = {}
        # Extract just the file path (before any " - " separator)
        raw_path = path_match.group(1).strip()
        # Remove trailing " - Error:" or " - No ..." parts from path
        path_clean = re.split(r'\s+-\s+(?:Error|No\s)', raw_path)[0].strip()
        record["file_path"] = path_clean

        # Check for "no sheet found" type messages
        no_sheet_match = re.search(r"No '?cont_infl'? or '?const_infl'? sheet", block, re.IGNORECASE)
        if no_sheet_match:
            record["no_relevant_sheet"] = True

        # Check for error
        error_match = re.search(r'[Ee]rror:\s*(.+?)(?:\n|$)', block)
        if error_match:
            record["error"] = error_match.group(1).strip()

        # Extract abundance unit (flexible matching)
        unit_match = re.search(r'[Aa]bundance\s+[Uu]nits?:\s*(.+?)(?:\n|$)', block)
        if unit_match:
            record["abundance_unit"] = unit_match.group(1).strip()

        # Extract time points count
        tp_match = re.search(r'[Nn]umber\s+of\s+[Tt]ime\s+[Pp]oints?:\s*(\d+)', block)
        if tp_match:
            record["time_points"] = int(tp_match.group(1))
        else:
            tp_match2 = re.search(r'[Tt]ime\s+[Pp]oints?:\s*(\d+)', block)
            if tp_match2:
                record["time_points"] = int(tp_match2.group(1))

        # Extract number of components
        nc_match = re.search(r'[Nn]umber\s+of\s+(?:gas-phase\s+)?[Cc]omponents?:\s*(\d+)', block)
        if nc_match:
            record["num_components"] = int(nc_match.group(1))

        # Extract component names
        names_match = re.search(r'[Cc]omponent\s+[Nn]ames?:\s*(.+?)(?:\n|$)', block)
        if names_match:
            record["component_names"] = names_match.group(1).strip()
        else:
            name_matches = re.findall(r'Name:\s*([^,\n]+)', block)
            if name_matches:
                particle_keys = {'seed component', 'concentration', 'mean radius',
                                 'seed name', 'particle concentration', 'particle radius'}
                gas_names = [n.strip() for n in name_matches
                            if n.strip().lower() not in particle_keys]
                if gas_names:
                    record["component_names"] = ", ".join(gas_names)
                    if not nc_match:
                        record["num_components"] = len(gas_names)

        # Extract seed/particle components
        seed_match = re.search(r'[Ss]eed\s+(?:component|name)[s]?:\s*(.+?)(?:\n|$)', block)
        if seed_match:
            record["seed_components"] = seed_match.group(1).strip()
        else:
            particle_section = re.search(r'[Pp]article[-\s][Pp]hase\s+[Pp]roperties?:(.+?)(?=\n\S|\Z)',
                                         block, re.DOTALL)
            if particle_section:
                seed_in_particle = re.search(r'[Ss]eed\s+[Cc]omponent:\s*(.+?)(?:\n|$)',
                                             particle_section.group(1))
                if seed_in_particle:
                    record["seed_components"] = seed_in_particle.group(1).strip()

        result["files"].append(record)

    return result if result["files"] else None


def normalize_path(p):
    return os.path.normpath(p.strip())


def paths_match(path1, path2):
    """Check if two paths refer to the same file, with flexible matching."""
    n1 = normalize_path(path1)
    n2 = normalize_path(path2)
    if n1 == n2:
        return True
    # Try basename matching as fallback
    if os.path.basename(n1) == os.path.basename(n2):
        return True
    # Try suffix matching (last N components)
    parts1 = n1.replace('\\', '/').split('/')
    parts2 = n2.replace('\\', '/').split('/')
    min_len = min(len(parts1), len(parts2))
    for n in range(1, min_len + 1):
        if parts1[-n:] == parts2[-n:]:
            return True
    return False


def find_matching_pred(pred_records, gold_path):
    """Find a predicted record that matches the gold path."""
    gold_norm = normalize_path(gold_path)
    for rec in pred_records["files"]:
        if paths_match(rec["file_path"], gold_path):
            return rec
    return None


