    file_size = os.path.getsize(pred_path)
    if file_size < 1024:
        return (False, f"Predicted PNG file is too small ({file_size} bytes), expected >1KB.")

    try:
        img = Image.open(pred_path)
        img.verify()
    except Exception as e:
        return (False, f"Predicted file is not a valid image: {e}")

    # Step 2: Check gold file exists
    if not os.path.exists(gold_path):
        return (False, "Gold result file not found at expected path.")

    try:
        gold_img = Image.open(gold_path)
        gold_img.verify()
    except Exception as e:
        return (False, f"Gold file is not a valid image: {e}")

    # Step 3: Compute expected PnL aggregation from source data
    try:
        trades = pd.read_csv(trade_log_path)
    except Exception as e:
        return (False, f"Could not load Trade Log CSV: {e}")

    realized = trades.dropna(subset=["Shares Sold", "Sell Price", "PnL"])
    expected_pnl = realized.groupby("Ticker")["PnL"].sum().sort_values(ascending=False)

    expected_tickers = list(expected_pnl.index)
    expected_values = list(expected_pnl.values)

    # Step 4: Compare predicted image against gold image using pixel similarity
    # Reload images for comparison
    try:
        pred_img_arr = mpimg.imread(pred_path)
        gold_img_arr = mpimg.imread(gold_path)
    except Exception as e:
        return (False, f"Could not read images for comparison: {e}")

    # Check that images have similar dimensions (allow some tolerance for DPI differences)
    pred_h, pred_w = pred_img_arr.shape[:2]
    gold_h, gold_w = gold_img_arr.shape[:2]

    # If dimensions differ significantly, the visualization is likely wrong
    dim_ratio_h = pred_h / gold_h if gold_h > 0 else 0
    dim_ratio_w = pred_w / gold_w if gold_w > 0 else 0

    if dim_ratio_h < 0.3 or dim_ratio_h > 3.0 or dim_ratio_w < 0.3 or dim_ratio_w > 3.0:
        return (False, f"Image dimensions differ significantly: pred ({pred_w}x{pred_h}) vs gold ({gold_w}x{gold_h}).")

