    if pred_resized.ndim == 3:
        non_white_mask = np.any(pred_resized < white_threshold, axis=2)
    else:
        non_white_mask = pred_resized < white_threshold

    non_white_fraction = np.mean(non_white_mask)

    if non_white_fraction < 0.05:
        return (False, "Predicted image has insufficient content - likely missing bars.")

    # Step 8: Additional lenient comparison - if the images are somewhat similar
    # and basic structural checks pass, accept it
    # Check that predicted image has similar amount of colored content as gold
    if gold_resized.ndim == 3:
        gold_non_white = np.any(gold_resized < white_threshold, axis=2)
    else:
        gold_non_white = gold_resized < white_threshold

    gold_non_white_fraction = np.mean(gold_non_white)
    content_ratio = non_white_fraction / gold_non_white_fraction if gold_non_white_fraction > 0 else 0

