        return (False, f"max_length mismatch: expected {gold_config['max_length']}, got {config.get('max_length')}")

    # Learning rate: allow small floating point tolerance
    pred_lr = config.get('learning_rate')
    gold_lr = gold_config['learning_rate']
    if pred_lr is None or abs(pred_lr - gold_lr) / max(abs(gold_lr), 1e-15) > 0.01:
        return (False, f"learning_rate mismatch: expected {gold_lr}, got {pred_lr}")

    # 5. Check training metrics structure
    if 'training_metrics' not in pred:
