    for key in required_metric_keys:
        if key not in metrics:
            return (False, f"Missing training metric: {key}")

    # Check that metrics have at least one entry
    for key in required_metric_keys:
        if not isinstance(metrics[key], list) or len(metrics[key]) == 0:
            return (False, f"Training metric '{key}' must be a non-empty list")

    # Verify metrics contain valid numerical values (not NaN or None)
    for key in ['loss', 'reward', 'val_reward']:
        for i, val in enumerate(metrics[key]):
            if val is None or (isinstance(val, float) and math.isnan(val)):
