        return (False, f"Gold result is not a valid PNG: {e}")

    # Step 4: Compute ground truth max PnL per ticker from source CSV
    # This validates the data processing aspect
    if not os.path.exists(csv_path):
        return (False, f"Source CSV not found at '{csv_path}'.")

    df = pd.read_csv(csv_path)
    df_filtered = df[df["Ticker"] != "TOTAL"]
