    pred_arr = np.array(pred_resized, dtype=np.float32)
    gold_arr = np.array(gold_resized, dtype=np.float32)

    # Compute normalized mean absolute error
    mae = np.mean(np.abs(pred_arr - gold_arr)) / 255.0

    # A very strict threshold would reject different but correct charts.
    # We use a moderate threshold: charts with same data but slightly different
    # styling should still pass (mae < 0.15), while completely wrong charts fail.
    # Identical images: mae ~ 0.0; same data/different style: mae ~ 0.05-0.12;
    # wrong data: mae > 0.15
    if mae > 0.15:
