import os
import re


def parse_output(text):
    """Parse the output file with flexible format handling."""
    result = {"files": []}

    # Split by file entries
    blocks = re.split(r'\n(?=File(?:\s+\d+)?:\s*\S)', text)
    if not blocks:
        blocks = [text]

    for block in blocks:
        block = block.strip()
        if not block:
            continue

        # Check if this block starts with a File entry
        path_match = re.match(r'File(?:\s+\d+)?:\s*(.+?)(?:\s*-\s*|\n|$)', block)
        if not path_match:
            continue

        record = {}
        # Extract just the file path (before any " - " separator)
        raw_path = path_match.group(1).strip()
        # Remove trailing " - Error:" or " - No ..." parts from path
        path_clean = re.split(r'\s+-\s+(?:Error|No\s)', raw_path)[0].strip()
        record["file_path"] = path_clean

        # Check for "no sheet found" type messages
        no_sheet_match = re.search(r"No '?cont_infl'? or '?const_infl'? sheet", block, re.IGNORECASE)
        if no_sheet_match:
            record["no_relevant_sheet"] = True

        # Check for error
        error_match = re.search(r'[Ee]rror:\s*(.+?)(?:\n|$)', block)
        if error_match:
            record["error"] = error_match.group(1).strip()

        # Extract abundance unit (flexible matching)
        unit_match = re.search(r'[Aa]bundance\s+[Uu]nits?:\s*(.+?)(?:\n|$)', block)
        if unit_match:
            record["abundance_unit"] = unit_match.group(1).strip()

