import json
import os


def parse_fasta(fasta_path):
    """Parse FASTA file and return list of (id, sequence) tuples."""
    entries = []
    current_id = None
    current_seq = []

    with open(fasta_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('>'):
                if current_id is not None:
                    full_seq = ''.join(current_seq)
                    entries.append((current_id, full_seq))
                    current_seq = []
                # Extract identifier - just the first word after '>'
                current_id = line[1:].split()[0] if line[1:].strip() else line[1:]
            else:
                if current_id is not None:
                    current_seq.append(line)
        # Handle last entry
        if current_id is not None:
            full_seq = ''.join(current_seq)
            entries.append((current_id, full_seq))

    return entries


def find_field(entry, possible_names):
    """Find a field value from a dict using multiple possible field names."""
    for name in possible_names:
        if name in entry:
            return entry[name]
    return None


def eval():
    pred_path = "pred_results/pred_datasets.json"
    fasta_path = "benchmark/datasets/tape/tape/example.fasta"

    # Step 1: Check file existence
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")

    if not os.path.exists(fasta_path):
        return (False, f"Source FASTA file not found: {fasta_path}")

    # Step 2: Parse the source FASTA file to get ground truth
    try:
        fasta_entries = parse_fasta(fasta_path)
    except Exception as e:
        return (False, f"Error parsing FASTA file: {e}")

    if not fasta_entries:
        return (False, "No entries found in FASTA file")

    # Build ground truth lookup
    gold_by_id = {entry_id: seq for entry_id, seq in fasta_entries}

    # Step 3: Parse predicted JSON
    try:
        with open(pred_path, "r") as f:
            pred_data = json.load(f)
    except json.JSONDecodeError as e:
        return (False, f"Predicted output is not valid JSON: {e}")

    # Step 4: Verify structure is a list
    if not isinstance(pred_data, list):
        # Maybe it's a dict with a list inside
        if isinstance(pred_data, dict):
            # Try to find a list value
            for key, val in pred_data.items():
                if isinstance(val, list):
                    pred_data = val
                    break
            else:
                return (False, f"Predicted output should be a list, got dict with keys: {list(pred_data.keys())}")
        else:
            return (False, f"Predicted output should be a list, got {type(pred_data).__name__}")

    # Step 5: Compare entry count
    if len(pred_data) != len(fasta_entries):
        return (False, f"Entry count mismatch: predicted {len(pred_data)}, expected {len(fasta_entries)}")

    # Step 6: Validate each entry
    # Possible field name variations
    id_fields = ["id", "identifier", "entry_id", "protein_id", "accession", "name"]
    seq_fields = ["primary", "primary_sequence", "sequence", "seq", "protein_sequence", "amino_acids"]
    len_fields = ["protein_length", "sequence_length", "length", "len", "seq_length", "size"]

    errors = []
    pred_ids_found = set()

    for i, pred_entry in enumerate(pred_data):
        if not isinstance(pred_entry, dict):
            errors.append(f"Entry {i} is not a dictionary, got {type(pred_entry).__name__}")
            continue

        # Find the identifier field
        pred_id = find_field(pred_entry, id_fields)
        if pred_id is None:
            errors.append(f"Entry {i}: could not find identifier field (tried: {id_fields}), available keys: {list(pred_entry.keys())}")
            continue

        pred_id = str(pred_id)

        if pred_id not in gold_by_id:
