            continue

        pred_ids_found.add(pred_id)
        gold_seq = gold_by_id[pred_id]

        # Find and validate the sequence field
        pred_seq = find_field(pred_entry, seq_fields)
        if pred_seq is None:
            errors.append(f"Entry '{pred_id}': could not find sequence field (tried: {seq_fields}), available keys: {list(pred_entry.keys())}")
        else:
            pred_seq = str(pred_seq)
            if pred_seq != gold_seq:
                errors.append(f"Entry '{pred_id}': sequence mismatch (predicted length {len(pred_seq)}, expected length {len(gold_seq)})")

        # Find and validate the length field
        pred_len = find_field(pred_entry, len_fields)
        if pred_len is None:
            errors.append(f"Entry '{pred_id}': could not find length field (tried: {len_fields}), available keys: {list(pred_entry.keys())}")
        else:
            try:
                pred_len = int(pred_len)
            except (ValueError, TypeError):
                errors.append(f"Entry '{pred_id}': length field is not an integer: {pred_len}")
                pred_len = None

            if pred_len is not None and pred_len != len(gold_seq):
                errors.append(f"Entry '{pred_id}': length mismatch (predicted {pred_len}, expected {len(gold_seq)})")

    # Check all FASTA entries are present
    missing_ids = set(gold_by_id.keys()) - pred_ids_found
    if missing_ids:
        sample = list(missing_ids)[:5]
        errors.append(f"Missing {len(missing_ids)} entries from FASTA: {sample}")

    if errors:
