        elif isinstance(obj, dict):
            return any(json_contains_value(v, target_value, tolerance) for v in obj.values())
        elif isinstance(obj, list):
            return any(json_contains_value(item, target_value, tolerance) for item in obj)
        elif isinstance(obj, str):
