        if gold_seq is None:
            return (False, f"Predicted entry {i} has identifier '{p_id}' not found in FASTA file")

        # Validate sequence matches
        if p_seq != gold_seq:
            return (False, f"Sequence mismatch for '{p_id}': predicted length {len(p_seq)}, expected length {len(gold_seq)}")

        # Validate length matches gold sequence length
        if p_len_int != len(gold_seq):
            return (False, f"Length mismatch for '{p_id}': predicted {p_len_int}, expected {len(gold_seq)}")

        matched += 1

    if matched != len(fasta_entries):
        return (False, f"Only {matched}/{len(fasta_entries)} entries matched")

