import json
import os
import numpy as np


def eval():
    pred_path = "pred_results/pred_cmvn.json"

    # Check file existence
    if not os.path.exists(pred_path):
        return (False, "Predicted output file pred_results/pred_cmvn.json not found")

    # Load files
    try:
        with open(pred_path) as f:
            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as e:
        return (False, f"Failed to parse predicted JSON: {e}")

    # Try to extract data from multiple possible JSON structures
    # Structure 1: Top-level keys per method (e.g., {"basic_cmvn": {"shape": ..., "mean": ..., "std": ...}})
    # Structure 2: Top-level keys for stats (e.g., {"shapes": {"basic": ...}, "means": {"basic": ...}, "stds": {"basic": ...}})
    # Structure 3: Mixed or other variations

    def find_method_data(pred, method_aliases):
        """Try to find shape, mean, std for a method given possible key aliases."""
        # Try structure 1: method as top-level key with nested stats
        for alias in method_aliases:
            if alias in pred and isinstance(pred[alias], dict):
                section = pred[alias]
                shape = None
                mean_val = None
                std_val = None
                for k in ["shape", "feature_shape", "feature_shapes"]:
                    if k in section:
                        shape = section[k]
                        break
                for k in ["mean", "means", "mean_values"]:
                    if k in section:
                        mean_val = section[k]
                        break
                for k in ["std", "standard_deviations", "std_values", "standard_deviation", "stds", "variance"]:
                    if k in section:
                        std_val = section[k]
                        break
                if shape is not None and mean_val is not None and std_val is not None:
                    return shape, mean_val, std_val

        # Try structure 2: stats as top-level keys, methods as sub-keys
        # Look for shapes/means/stds at top level
        shapes_section = None
        means_section = None
        stds_section = None

        for k in ["shapes", "shape", "feature_shapes"]:
            if k in pred and isinstance(pred[k], dict):
                shapes_section = pred[k]
                break

        for k in ["means", "mean", "mean_values"]:
            if k in pred and isinstance(pred[k], dict):
                means_section = pred[k]
                break

        for k in ["stds", "std", "standard_deviations", "variances"]:
            if k in pred and isinstance(pred[k], dict):
                stds_section = pred[k]
                break

        if shapes_section is not None and means_section is not None and stds_section is not None:
            shape = None
            mean_val = None
            std_val = None

            for alias in method_aliases:
                if alias in shapes_section:
                    shape = shapes_section[alias]
                    break
            for alias in method_aliases:
                if alias in means_section:
                    mean_val = means_section[alias]
                    break
            for alias in method_aliases:
                if alias in stds_section:
                    std_val = stds_section[alias]
                    break

            if shape is not None and mean_val is not None and std_val is not None:
                return shape, mean_val, std_val

        return None, None, None

    # Define aliases for each method
    basic_aliases = ["basic", "cmvn_features", "basic_cmvn", "basic_cmvn_features", "global_cmvn"]
    collection_aliases = ["collection", "collection_cmvn_features", "collection_cmvn",
                          "collection_based_cmvn", "multi_utterance_cmvn"]
    sliding_aliases = ["sliding", "sliding_window_cmvn_features", "sliding_window_cmvn",
                       "sliding_cmvn", "window_cmvn"]

    methods_config = [
        ("basic_cmvn", basic_aliases, 0.3, 0.5, 2.0),
        ("collection_cmvn", collection_aliases, 0.5, 0.3, 2.5),
        ("sliding_window_cmvn", sliding_aliases, 0.5, 0.3, 2.5),
    ]

    reasons = []

    for method_name, aliases, mean_threshold, std_low, std_high in methods_config:
        shape, mean_val, std_val = find_method_data(pred, aliases)

        if shape is None:
            return (False, f"Missing data for {method_name} in predicted results. "
                          f"Tried aliases: {aliases}. Available keys: {list(pred.keys())}")
        if mean_val is None:
            return (False, f"{method_name}: missing mean field")
        if std_val is None:
            return (False, f"{method_name}: missing std field")

        # Validate shape: should contain 100 frames and 13 features
        if isinstance(shape, list):
            flat_shape = shape
            if 13 not in flat_shape:
                return (False, f"{method_name}: expected 13 features in shape, got {shape}")
            if 100 not in flat_shape:
                return (False, f"{method_name}: expected 100 frames in shape, got {shape}")
        else:
            return (False, f"{method_name}: shape should be a list/array, got {type(shape)}: {shape}")

        # Convert mean and std to numpy arrays
        mean_arr = np.array(mean_val)
        std_arr = np.array(std_val)

        mean_flat = mean_arr.flatten()
        std_flat = std_arr.flatten()

        # Check that we have 13 values (one per dimension)
        if len(mean_flat) != 13:
            return (False, f"{method_name}: expected 13 mean values, got {len(mean_flat)}")
        if len(std_flat) != 13:
            return (False, f"{method_name}: expected 13 std values, got {len(std_flat)}")

        # Check mean: should be close to zero (normalized features)
        max_abs_mean = np.max(np.abs(mean_flat))
        if max_abs_mean >= mean_threshold:
            return (False, f"{method_name}: mean not close enough to zero. "
                          f"Max |mean| = {max_abs_mean:.6f}, threshold = {mean_threshold}")

        # Check std: should be reasonable (normalized features)
        min_std = np.min(std_flat)
        max_std = np.max(std_flat)
        if min_std < std_low or max_std > std_high:
            return (False, f"{method_name}: std not in expected range. "
                          f"Range [{min_std:.6f}, {max_std:.6f}], expected ({std_low}, {std_high})")

        reasons.append(
            f"{method_name}: shape={shape}, mean OK (max |mean|={max_abs_mean:.4e}), "
            f"std OK (range [{min_std:.4f}, {max_std:.4f}])"
        )

    return (True, "All CMVN methods pass. " + "; ".join(reasons))


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")---
