    # Original image is ~400x300, so side-by-side should be ~800x300
    if w < 400 or h < 100:
        return (False, f"Image dimensions {w}x{h} too small for side-by-side comparison")

    # Width should be approximately twice the height (for side-by-side layout)
    aspect_ratio = w / h
    if aspect_ratio < 1.3:
        return (False, f"Image aspect ratio {aspect_ratio:.2f} does not suggest side-by-side layout (expected >= 1.3)")

    # Step 4: Check for green rectangle in left panel
    # The left half should contain the original image with a green rectangle
    mid_w = w // 2
    left_panel = pred_img[:, :mid_w, :]

