    # Being more flexible with green detection thresholds
    green_mask = (left_panel[:, :, 0] < 80) & (left_panel[:, :, 1] > 150) & (left_panel[:, :, 2] < 80)
    green_pixel_count = green_mask.sum()

    if green_pixel_count < 20:
        return (False, f"Green rectangle not detected in left panel (only {green_pixel_count} green pixels found, expected >20)")

    # Step 5: Verify right panel shows detection result (should differ from left panel)
    right_panel = pred_img[:, mid_w:, :]
    left_mean = left_panel.mean()
    right_mean = right_panel.mean()

    # The filtered result should differ from original image
    # After backprojection + morphological ops, the right panel should look different
    if abs(left_mean - right_mean) < 5:
