    # Step 6: Check that right panel has characteristics of a detection mask
    # Backprojection result after morphological ops should be mostly dark with some bright regions
    # or at least significantly different from the original color image
    right_panel_gray = cv2.cvtColor(right_panel, cv2.COLOR_BGR2GRAY)

