import json
import os


def get_nested_value(d, *keys):
    """Try multiple possible key names and return the first found value."""
    for key in keys:
        if key in d:
            return d[key]
    return None


def flatten_analysis(pred):
    """Extract analysis components regardless of nesting structure."""
    relations = pred.get("detected_relations", pred.get("relations", None))
    inferred_facts = pred.get("inferred_facts", None)
    aggregate_concepts = pred.get("aggregate_concepts", None)
    sequence_links = pred.get("sequence_links", None)

    # Try nested under analysis_results
    if "analysis_results" in pred:
        ar = pred["analysis_results"]
        if relations is None:
            relations = ar.get("detected_relations", ar.get("relations", []))
        if inferred_facts is None:
            inferred_facts = ar.get("inferred_facts", [])
        if aggregate_concepts is None:
            aggregate_concepts = ar.get("aggregate_concepts", [])
        if sequence_links is None:
            sequence_links = ar.get("sequence_links", [])

    return (
        relations or [],
        inferred_facts or [],
        aggregate_concepts or [],
        sequence_links or []
    )


def get_main_node_text(main_node):
    """Extract text content from main node regardless of field name."""
    if not main_node:
        return ""
    for field in ["content", "memory", "text", "description", "node_content"]:
        if field in main_node and main_node[field]:
            return main_node[field].lower()
    return str(main_node).lower()


def get_relation_info(rel):
    """Extract relation info regardless of field naming conventions."""
    if not isinstance(rel, dict):
        return None, None, None

    source = get_nested_value(rel, "source", "source_id", "from", "from_id", "node1")
    target = get_nested_value(rel, "target", "target_id", "to", "to_id", "node2")
