def eval():
    pred_dir = "pred_results"
    gold_dir = "./gold_results/"

    # === Step 1: Verify output file existence and format ===
    required_files = [
        "pred_01_dwd_krige_variogram.png",
        "pred_01_dwd_krige_temp_field.csv",
        "pred_01_dwd_krige_mean_field.csv",
        "pred_01_dwd_krige_temperature_maps.png",
        "pred_01_dwd_krige_cross_section.png",
        "pred_01_dwd_krige_model_info.txt",
    ]

    for f in required_files:
        pred_path = os.path.join(pred_dir, f)
        if not os.path.exists(pred_path):
            return (False, f"Missing required output file: {f}")

    # Verify PNG files are valid images
    for png_file in [f for f in required_files if f.endswith(".png")]:
        try:
            img = Image.open(os.path.join(pred_dir, png_file))
            img.verify()
        except Exception as e:
            return (False, f"Invalid PNG file {png_file}: {e}")

    # Load temperature and mean fields
    try:
        pred_temp = np.loadtxt(os.path.join(pred_dir, "pred_01_dwd_krige_temp_field.csv"), delimiter=",")
        pred_mean = np.loadtxt(os.path.join(pred_dir, "pred_01_dwd_krige_mean_field.csv"), delimiter=",")
    except Exception as e:
        return (False, f"Failed to load CSV files: {e}")

    # Check dimensions: grid should be ~92 x 112 (lat 47-56.1, lon 5-16.1, 0.1 res)
    expected_rows = len(np.arange(47, 56.1, 0.1))  # 92
    expected_cols = len(np.arange(5, 16.1, 0.1))    # 112
    if pred_temp.shape != (expected_rows, expected_cols):
        return (False, f"Temperature field has wrong dimensions: {pred_temp.shape}, expected ({expected_rows}, {expected_cols})")
    if pred_mean.shape != (expected_rows, expected_cols):
        return (False, f"Mean field has wrong dimensions: {pred_mean.shape}, expected ({expected_rows}, {expected_cols})")

    # === Step 2: Validate variogram model parameters ===
    try:
        with open(os.path.join(pred_dir, "pred_01_dwd_krige_model_info.txt"), "r") as f:
            model_text = f.read()
    except Exception as e:
        return (False, f"Failed to read model_info.txt: {e}")

    # Check that Spherical model was used
    if "spherical" not in model_text.lower():
        return (False, "Model info does not indicate a Spherical variogram model")

    # Extract parameters - try structured format first, then fallback to text parsing
    variance = None
    len_scale = None
    nugget = None

    # Parse from gstools model repr like "Spherical(latlon=True, var=13.2, len_scale=5.96e+02, ...)"
    var_match = re.search(r"\bvar\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)", model_text)
    if var_match:
        variance = float(var_match.group(1))
    ls_match = re.search(r"\blen_scale\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)", model_text)
    if ls_match:
        len_scale = float(ls_match.group(1))
    nug_match = re.search(r"\bnugget\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)", model_text)
    if nug_match:
        nugget = float(nug_match.group(1))

    # Also try key-value format (e.g., "variance: 13.19")
    for line in model_text.split("\n"):
        key_val = line.strip().split(":")
        if len(key_val) >= 2:
            key = key_val[0].strip().lower()
            val_str = ":".join(key_val[1:])
            match = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", val_str)
            if match:
                val = float(match.group())
                if key in ("variance", "sill", "var") and variance is None:
                    variance = val
                elif key in ("len_scale", "range", "length_scale") and len_scale is None:
                    len_scale = val
                elif key == "nugget" and nugget is None:
                    nugget = val

    if variance is None:
        return (False, "Could not extract variance/sill from model_info.txt")
    if len_scale is None:
        return (False, "Could not extract len_scale/range from model_info.txt")
    if nugget is None:
        nugget = 0.0  # Default assumption

    # Validate parameter ranges
    if variance <= 0:
        return (False, f"Sill/variance must be positive, got {variance}")
    if nugget < 0:
        return (False, f"Nugget must be non-negative, got {nugget}")
    if nugget >= variance:
        return (False, f"Nugget ({nugget}) should be less than sill/variance ({variance})")
    # len_scale is in km (geo_scale=KM_SCALE), range should be reasonable (50-2000 km)
    # The gold has ~596 km which is reasonable for Germany
    if len_scale < 10 or len_scale > 5000:
        return (False, f"len_scale/range {len_scale} km is outside reasonable bounds [10, 5000]")

    # === Step 3: Compare predicted fields against gold standard ===
    try:
        gold_temp = np.loadtxt(os.path.join(gold_dir, "pred_01_dwd_krige_temp_field.csv"), delimiter=",")
        gold_mean = np.loadtxt(os.path.join(gold_dir, "pred_01_dwd_krige_mean_field.csv"), delimiter=",")
    except Exception as e:
        return (False, f"Failed to load gold standard CSV files: {e}")

    if pred_temp.shape != gold_temp.shape:
        return (False, f"Temperature field shape mismatch: pred {pred_temp.shape} vs gold {gold_temp.shape}")
    if pred_mean.shape != gold_mean.shape:
        return (False, f"Mean field shape mismatch: pred {pred_mean.shape} vs gold {gold_mean.shape}")

    # Compute comparison metrics for temperature field
    temp_diff = pred_temp - gold_temp
    temp_rmse = np.sqrt(np.mean(temp_diff ** 2))
    temp_mae = np.mean(np.abs(temp_diff))
    # R^2 between predicted and gold
    ss_res = np.sum(temp_diff ** 2)
    ss_tot = np.sum((gold_temp - np.mean(gold_temp)) ** 2)
    temp_r2 = 1.0 - ss_res / ss_tot if ss_tot > 0 else 0.0

    # Compute comparison metrics for mean field
    mean_diff = pred_mean - gold_mean
    mean_rmse = np.sqrt(np.mean(mean_diff ** 2))

    # Thresholds for comparison against gold
    # Allow some tolerance since different implementations/versions might give slightly different results
    if temp_rmse > 2.5:
        return (False, f"Temperature field RMSE vs gold too high: {temp_rmse:.4f} (threshold: 2.5)")
    if temp_r2 < 0.60:
        return (False, f"Temperature field R^2 vs gold too low: {temp_r2:.4f} (threshold: 0.60)")
    if mean_rmse > 2.0:
        return (False, f"Mean drift field RMSE vs gold too high: {mean_rmse:.4f} (threshold: 2.0)")

    # === Step 4: Validate physical plausibility ===
    if np.any(np.isnan(pred_temp)) or np.any(np.isinf(pred_temp)):
        return (False, "Temperature field contains NaN or infinite values")
    if np.any(np.isnan(pred_mean)) or np.any(np.isinf(pred_mean)):
        return (False, "Mean field contains NaN or infinite values")

    # Check temperature bounds (reasonable for German climate data)
    if np.min(pred_temp) < -10 or np.max(pred_temp) > 40:
        return (False, f"Temperature field values out of plausible range: [{np.min(pred_temp):.1f}, {np.max(pred_temp):.1f}]")

    # Check north-south gradient in mean field: southern latitudes should generally be warmer
    # Compare mean of bottom rows (south) vs top rows (north)
    south_mean = np.mean(pred_mean[-10:, :])
    north_mean = np.mean(pred_mean[:10, :])
    # In the gold, south (high lat index = higher lat = north) actually has LOWER temps
    # Wait - g_lat goes from 47 (south) to 56 (north), so index 0 = south, last = north
    # For Germany in summer, south is typically warmer
    south_mean_temp = np.mean(pred_mean[:10, :])   # lat ~47-48 (south)
    north_mean_temp = np.mean(pred_mean[-10:, :])   # lat ~55-56 (north)
    # Just check that there IS a gradient (difference > 0.5 degrees)
    if abs(south_mean_temp - north_mean_temp) < 0.5:
        return (False, "Mean drift field does not show expected north-south temperature gradient")

    # === Step 5: Final result ===
    details = (
        f"All checks passed. "
        f"Temp field RMSE vs gold: {temp_rmse:.4f}, R^2: {temp_r2:.4f}. "
        f"Mean field RMSE vs gold: {mean_rmse:.4f}. "
        f"Variogram params - variance: {variance:.2f}, len_scale: {len_scale:.1f} km, nugget: {nugget:.2f}. "
        f"Temp range: [{np.min(pred_temp):.1f}, {np.max(pred_temp):.1f}]."
    )
    return (True, details)


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")"}

