"""
Evaluation script for AT domain signature matching task.
Checks both format validity and semantic correctness of predictions.
"""

import json
import os
from typing import Dict, Any, Tuple, List, Union
from Bio import SeqIO


def load_json_file(filepath: str) -> Dict[str, Any]:
    """Load and parse a JSON file."""
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {filepath}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in {filepath}: {e}")


def get_predictions_list(domain_data: Any) -> Tuple[bool, List, str]:
    """Extract predictions list from domain data, supporting multiple formats."""
    if isinstance(domain_data, list):
        return True, domain_data, ""
    elif isinstance(domain_data, dict):
        if "predictions" in domain_data:
            preds = domain_data["predictions"]
            if isinstance(preds, list):
                return True, preds, ""
            else:
                return False, [], f"'predictions' field must be a list, got {type(preds)}"
        elif "score" in domain_data:
            return True, [domain_data], ""
        else:
            return False, [], f"Domain data dict missing 'predictions' key"
    elif domain_data is None:
        return True, [], ""
    else:
        return False, [], f"Domain data must be a list or dict, got {type(domain_data)}"


def extract_score(pred: Any) -> Tuple[bool, float, str]:
    """Extract score from a prediction entry."""
    if isinstance(pred, dict):
        if "score" in pred:
            score = pred["score"]
            if isinstance(score, (int, float)):
                return True, float(score), ""
            else:
                return False, 0.0, f"Score must be a number, got {type(score)}: {score}"
        else:
            return False, 0.0, f"Prediction dict missing 'score' field: {pred}"
    elif isinstance(pred, (int, float)):
        return True, float(pred), ""
    else:
        return False, 0.0, f"Prediction must be a dict or number, got {type(pred)}: {pred}"


def compute_reference_results() -> Dict[str, Any]:
    """
    Compute the expected results using the reference algorithm.
    Returns a dict mapping domain_id -> list of (ref_id, score) tuples above 50%.
    """
    positions_path = 'benchmark/datasets/antismash/antismash/modules/nrps_pks/at_analysis/data/ATpositions.txt'
    domains_path = 'benchmark/datasets/antismash/antismash/modules/nrps_pks/at_analysis/data/AT_domains_muscle.fasta'
    signatures_path = 'benchmark/datasets/antismash/antismash/modules/nrps_pks/at_analysis/data/pks_signatures.fasta'

    # Read reference positions
    with open(positions_path, 'r') as f:
        line = f.readline().strip()
    positions = [int(x) - 1 for x in line.split()]  # Convert to 0-based indices

    # Parse domain sequences and extract signatures
    domain_signatures = {}
    for record in SeqIO.parse(domains_path, 'fasta'):
        seq = str(record.seq)
        signature = ''.join([seq[i] for i in positions if i < len(seq)])
        domain_signatures[record.id] = signature

    # Parse reference signatures
    reference_signatures = {}
    for record in SeqIO.parse(signatures_path, 'fasta'):
        reference_signatures[record.id] = str(record.seq)

    # Calculate match scores
    results = {}
    for domain_id, domain_sig in domain_signatures.items():
        predictions = []
        for ref_id, ref_sig in reference_signatures.items():
            # Calculate percentage match
            min_len = min(len(domain_sig), len(ref_sig))
            if min_len == 0:
                continue
            matches = sum(1 for a, b in zip(domain_sig, ref_sig) if a == b)
            score = (matches / min_len) * 100
            if score > 50:
                predictions.append((ref_id, score))
        results[domain_id] = predictions

    return results, domain_signatures, reference_signatures, positions


def validate_structure(data: Dict[str, Any]) -> Tuple[bool, str]:
    """Validate the overall JSON structure."""
    if not isinstance(data, dict):
        return False, "Root structure must be a dictionary"
    if len(data) == 0:
        return False, "JSON must contain at least one domain entry"
    return True, "Structure valid"


def validate_all_predictions(data: Dict[str, Any]) -> Tuple[bool, str, Dict]:
    """Validate all predictions and extract them in a normalized format."""
    normalized = {}
    for domain_id, domain_data in data.items():
        success, predictions, err = get_predictions_list(domain_data)
        if not success:
            return False, f"Domain '{domain_id}': {err}", {}
        normalized_preds = []
        for i, pred in enumerate(predictions):
            score_ok, score, err = extract_score(pred)
            if not score_ok:
                return False, f"Domain '{domain_id}' prediction {i}: {err}", {}
            normalized_preds.append({"score": score, "original": pred})
        normalized[domain_id] = normalized_preds
    return True, "All predictions valid", normalized


def eval() -> Tuple[bool, str]:
    """
    Main evaluation function.
    Returns (success: bool, reason: str)
    """
    pred_file = "pred_results/pred_at_analysis.json"

    try:
        # Step 1: Check file exists
        if not os.path.exists(pred_file):
            return False, f"Prediction file not found: {pred_file}"

        # Step 2: Load JSON
        pred_data = load_json_file(pred_file)

        # Step 3: Validate overall structure
        valid, msg = validate_structure(pred_data)
        if not valid:
            return False, f"Structure validation failed: {msg}"

        # Step 4: Validate and normalize all predictions
        valid, msg, normalized = validate_all_predictions(pred_data)
        if not valid:
            return False, f"Prediction validation failed: {msg}"

