                        return False, f"H5 {split_key} obs/action count mismatch"
                    if not np.allclose(action_data, 0, atol=1e-5):
                        return False, f"H5 {split_key} actions should be dummy zeros"

            # Check training data has reasonable number of samples
            train_key = next((k for k in ["train", "training"] if k in pred_h5), None)
            if train_key:
                train_group = pred_h5[train_key]
                obs_key = next(k for k in ["observations", "obs", "observation"] if k in train_group)
                train_obs = train_group[obs_key][:]
                min_expected = 100 * 11  # At minimum, training transitions
                if train_obs.shape[0] < min_expected * 0.8:
                    return False, f"H5 train has too few observations: {train_obs.shape[0]}, expected at least ~{min_expected}"

        elif has_grouped:
            # Grouped structure with sample_0, sample_1, ...
            sample_keys = sorted([k for k in h5_keys if k.startswith("sample_")])
            n_samples = len(sample_keys)

            if n_samples < 2:
                return False, f"Too few samples in H5: {n_samples}"

            first_sample = pred_h5[sample_keys[0]]
            sample_subkeys = list(first_sample.keys())

            has_obs = any(k in first_sample for k in ["obs", "observation", "observations"])
            has_action = any(k in first_sample for k in ["action", "actions"])

            if not has_obs:
                return False, f"H5 sample missing obs key. Keys: {sample_subkeys}"
            if not has_action:
                return False, f"H5 sample missing action key. Keys: {sample_subkeys}"

        else:
            # Some other structure - just check it has data
            first_key = h5_keys[0]
            try:
                # Could be a group
                item = pred_h5[first_key]
                if isinstance(item, h5py.Dataset):
                    data = item[:]
                    if data.size == 0:
                        return False, f"H5 first dataset '{first_key}' is empty"
                elif isinstance(item, h5py.Group):
                    subkeys = list(item.keys())
                    if len(subkeys) == 0:
                        return False, f"H5 first group '{first_key}' is empty"
            except Exception as e:
                return False, f"Cannot read H5 data: {e}"

    finally:
        pred_h5.close()

    return True, "All checks passed: file structure, data shapes, quality, color content, and replay buffer format are correct."


