                    if comp_col is not None and r2_cv_col is not None and comp_col != r2_cv_col:
                        comp_df = df
                        break

                    # If only 2 columns, use first as components, second as scores
                    if len(df.columns) == 2:
                        comp_col = df.columns[0]
                        r2_cv_col = df.columns[1]
                        comp_df = df
                        break
                except Exception:
                    continue

            if comp_df is None:
                return False, "Could not parse component selection CSV"

