    """Load molecules from SDF file"""
    molecules = []
    smiles_strings = []

    try:
        suppl = Chem.SDMolSupplier(file_path)
        for mol in suppl:
            if mol is not None:
                smiles = Chem.MolToSmiles(mol)
                smiles_strings.append(smiles)
