def load_results_csv(filepath):
    """
    Try to load results CSV flexibly - handles both indexed and non-indexed formats.
    Returns a DataFrame with 'Actual', 'Predicted', 'Dataset' columns.
    """
    required_columns = ['Actual', 'Predicted', 'Dataset']

    # Try without index first
    try:
        df = pd.read_csv(filepath)
        if all(col in df.columns for col in required_columns):
            return df, None
    except Exception:
        pass

    # Try with index_col=0
    try:
        df = pd.read_csv(filepath, index_col=0)
        if all(col in df.columns for col in required_columns):
            return df, None
    except Exception:
        pass

    # Try resetting index if index might be one of the required columns
    try:
        df = pd.read_csv(filepath, index_col=0)
        df = df.reset_index()
        if 'index' in df.columns and 'Actual' not in df.columns:
            df = df.rename(columns={'index': 'Actual'})
        if all(col in df.columns for col in required_columns):
            return df, None
    except Exception:
        pass

