    missing_cols = [col for col in required_stats_columns if col not in stats_df.columns]
    if missing_cols:
        return False, f"Statistics CSV missing required columns: {missing_cols}. Got: {stats_df.columns.tolist()}"

    if len(stats_df) == 0:
        return False, "Statistics CSV is empty"

    stats = stats_df.iloc[0]

    # Step 3: Calculate expected statistics from input data
    mw_list = []
    for _, row in input_data.iterrows():
        try:
            m_val = row['M']
            if pd.isna(m_val) or str(m_val) == 'nan':
                mw_list.append(0.0)
                continue
            parsed = ast.literal_eval(str(m_val))
            if isinstance(parsed, list):
                mw_list.append(sum(parsed))
            elif isinstance(parsed, (int, float)):
                mw_list.append(float(parsed))
            else:
                mw_list.append(0.0)
        except Exception:
            try:
                mw_list.append(float(row['M']))
            except Exception:
                mw_list.append(0.0)

    expected_avg_mw = sum(mw_list) / len(mw_list) if mw_list else 0
    expected_avg_salt_mol = input_data['Molality'].mean()

    # Step 4: Validate num_samples
    reported_num_samples = int(stats['num_samples'])
    if reported_num_samples <= 0:
        return False, f"num_samples must be positive, got {reported_num_samples}"

    completion_rate = reported_num_samples / expected_num_samples
    if completion_rate < 0.80:
        return False, (
            f"Too few samples processed: {reported_num_samples} out of "
            f"{expected_num_samples} ({completion_rate*100:.1f}%)"
        )

    # Step 5: Validate average molecular weight (allow 10% tolerance)
    reported_avg_mw = float(stats['avg_mw'])
    if reported_avg_mw <= 0:
        return False, f"Average molecular weight must be positive, got {reported_avg_mw}"

    if expected_avg_mw > 0:
        mw_error = abs(reported_avg_mw - expected_avg_mw) / expected_avg_mw
        if mw_error > 0.10:
            return False, (
                f"Average molecular weight significantly differs from expected. "
                f"Expected ~{expected_avg_mw:.2f}, got {reported_avg_mw:.2f} "
                f"(error: {mw_error*100:.1f}%)"
            )

    # Step 6: Validate average molality (allow 10% tolerance)
    reported_avg_salt_mol = float(stats['avg_salt_mol'])
    if reported_avg_salt_mol <= 0:
        return False, f"Average molality must be positive, got {reported_avg_salt_mol}"

    if expected_avg_salt_mol > 0:
        mol_error = abs(reported_avg_salt_mol - expected_avg_salt_mol) / expected_avg_salt_mol
        if mol_error > 0.10:
            return False, (
                f"Average molality significantly differs from expected. "
                f"Expected ~{expected_avg_salt_mol:.4f}, got {reported_avg_salt_mol:.4f} "
                f"(error: {mol_error*100:.1f}%)"
            )

