            return False, f"Data list pickle should contain a list, got {type(data_list)}"

        # Allow empty or small data_list if stats are correct
        # The main value is in the stats CSV and DataFrame
        # But do a basic size check - should have processed at least some data
        if len(data_list) == 0:
            # Check if the pkl file has reasonable size (might have been saved before processing)
            pkl_size = os.path.getsize(pkl_file)
            # Empty list is acceptable if stats are correct - warn but don't fail
            # The task primarily requires correct stats
            print(f"Warning: Data list is empty (pkl size: {pkl_size} bytes)")
            # Don't fail here - the stats CSV is the primary output
        else:
            pkl_completion = len(data_list) / expected_num_samples
            if pkl_completion < 0.50:
                print(f"Warning: Only {len(data_list)} items in data list out of {expected_num_samples} expected")

