        print(f"Note: Could not load pickle due to missing module: {e}")
    except Exception as e:
        return False, f"Failed to load pickle file {pkl_file}: {str(e)}"

    # Step 8: Load and validate DataFrame pickle
    try:
        df = pd.read_pickle(df_pkl_file)

        if not isinstance(df, pd.DataFrame):
            return False, f"DataFrame pickle should contain a DataFrame, got {type(df)}"

        if len(df) == 0:
            return False, "DataFrame is empty"

