        df_size = os.path.getsize(df_pkl_file)
        if df_size < 100:
            return False, f"DataFrame pickle is too small ({df_size} bytes), likely empty or corrupt"
        print(f"Note: Could not fully load DataFrame pickle due to missing module: {e}")
    except Exception as e:
        return False, f"Failed to load DataFrame pickle {df_pkl_file}: {str(e)}"

    success_message = (
        f"Evaluation passed! Successfully processed {reported_num_samples} samples "
        f"({completion_rate*100:.1f}% of {expected_num_samples} total). "
        f"All output files correctly formatted. "
        f"Average molecular weight: {reported_avg_mw:.2f}, "
        f"Average molality: {reported_avg_salt_mol:.4f}"
    )

