            opensky_data, opensky_dir, "opensky"
        )
        if not opensky_consistent:
            return False, f"OpenSky data: {opensky_reason}"

        return True, "Consistency validation passed"

    except Exception as e:
        return False, f"Consistency validation error: {str(e)}"


def check_dataset_consistency(data, data_dir, dataset_name):
    """
    Check consistency for a single dataset against actual files.
    """
    if data is None:
        return False, f"No data found for {dataset_name}"

    # Flatten the data structure for easier access
    flat_data = flatten_dict(data)

    # Check country_flows file
    country_flows_file = os.path.join(data_dir, 'country_flows.csv')
    if os.path.exists(country_flows_file):
        try:
            df = pd.read_csv(country_flows_file)
            actual_shape = list(df.shape)
            actual_cols = [c for c in df.columns if not c.startswith('Unnamed')]

            # Find reported shape and columns for country_flows
            reported_shape = None
            reported_cols = None

            for key, value in flat_data.items():
                if 'country_flows' in key.lower() or 'country_flow' in key.lower():
                    if 'shape' in key.lower() and isinstance(value, list):
                        reported_shape = value
                    if ('column' in key.lower() or 'col' in key.lower()) and isinstance(value, list):
                        reported_cols = value

            if reported_shape is not None:
                # Allow for minor differences (e.g., index column)
                if not (abs(reported_shape[0] - actual_shape[0]) <= 1 and
                       abs(reported_shape[1] - actual_shape[1]) <= 1):
                    return False, f"country_flows shape mismatch: reported {reported_shape}, actual {actual_shape}"

            if reported_cols is not None:
                # Columns should be a reasonable subset or match
                if not set(reported_cols).issubset(set(actual_cols)) and not set(actual_cols).issubset(set(reported_cols)):
                    # Allow if at least 80% of columns match
                    matching = len(set(reported_cols) & set(actual_cols))
                    if matching < 0.8 * max(len(reported_cols), len(actual_cols)):
                        return False, f"country_flows columns mismatch for {dataset_name}"

        except Exception as e:
            # Don't fail if we can't validate - just skip
            pass

    # Check country_fixed file
    country_fixed_file = os.path.join(data_dir, 'country_fixed.csv')
    if os.path.exists(country_fixed_file):
        try:
            df = pd.read_csv(country_fixed_file)
            actual_shape = list(df.shape)
            actual_cols = [c for c in df.columns if not c.startswith('Unnamed')]

            reported_shape = None
            reported_cols = None

            for key, value in flat_data.items():
                if 'country_fixed' in key.lower():
                    if 'shape' in key.lower() and isinstance(value, list):
                        reported_shape = value
                    if ('column' in key.lower() or 'col' in key.lower()) and isinstance(value, list):
                        reported_cols = value

            if reported_shape is not None:
                if not (abs(reported_shape[0] - actual_shape[0]) <= 1 and
                       abs(reported_shape[1] - actual_shape[1]) <= 1):
                    return False, f"country_fixed shape mismatch: reported {reported_shape}, actual {actual_shape}"

            if reported_cols is not None:
                if not set(reported_cols).issubset(set(actual_cols)) and not set(actual_cols).issubset(set(reported_cols)):
                    matching = len(set(reported_cols) & set(actual_cols))
                    if matching < 0.8 * max(len(reported_cols), len(actual_cols)):
                        return False, f"country_fixed columns mismatch for {dataset_name}"

        except Exception as e:
            pass

    # Check flights_df file
    flights_df_file = os.path.join(data_dir, 'flights_df.zip')
    if os.path.exists(flights_df_file):
        try:
            df = pd.read_csv(flights_df_file, compression='zip', nrows=100)
            actual_cols = [c for c in df.columns if not c.startswith('Unnamed')]

            reported_shape = None
            reported_cols = None

            for key, value in flat_data.items():
                if 'flights_df' in key.lower() or 'flight' in key.lower():
                    if 'shape' in key.lower() and isinstance(value, list):
                        reported_shape = value
                    if ('column' in key.lower() or 'col' in key.lower()) and isinstance(value, list):
                        reported_cols = value

            if reported_shape is not None:
                # Only check column count (row count can't be verified from sample)
                actual_col_count = len(df.columns)
                reported_col_count = reported_shape[1] if len(reported_shape) > 1 else 0
                if abs(reported_col_count - actual_col_count) > 1:
                    return False, f"flights_df column count mismatch: reported {reported_col_count}, actual {actual_col_count}"

            if reported_cols is not None:
                if not set(reported_cols).issubset(set(actual_cols)) and not set(actual_cols).issubset(set(reported_cols)):
                    matching = len(set(reported_cols) & set(actual_cols))
                    if matching < 0.8 * max(len(reported_cols), len(actual_cols)):
                        return False, f"flights_df columns mismatch for {dataset_name}"

        except Exception as e:
            pass

    return True, "Dataset consistency verified"


